const lugJobs: LugJob[] = [
  {slug:"kia/sportage/lug-nut-torque",keyword:"kia sportage lug nut torque spec",make:"Kia",model:"2022 Sportage",title:"2022 Kia Sportage Lug Nut Torque and Tightening Method",answer:"Kia specifies 79–94 lbf·ft (11–13 kgf·m, approximately 107–127 N·m) for the 2022 Sportage wheel lug nuts.",scope:"This exact permitted range comes from the 2022 Sportage tire-changing procedure. It applies to the original metric studs and matching chamfered nuts; aftermarket wheels or changed hardware require the wheel supplier's instructions.",detail:"Clean debris from the hub and wheel mating faces, place each nut by hand, lower the vehicle and tighten every other nut until all are secure. Use one repeatable setting within Kia's published range for every position rather than scattering final values across the range. Do not install a non-metric or mismatched-seat nut simply because it appears to thread onto the stud.",values:[{label:"Permitted torque range",value:"79–94 lbf·ft",note:"11–13 kgf·m; about 107–127 N·m"},{label:"Tightening order",value:"Every other nut",note:"Opposite-side/star sequence"},{label:"Hardware",value:"Metric, matching chamfer",note:"Reuse correct original style"},{label:"Final tool",value:"Calibrated torque wrench",note:"Do not finish by feel"}],source:kiaSportage2022,suv:true},
  {slug:"mazda/cx-5/lug-nut-torque",keyword:"mazda cx5 lug nut torque spec",make:"Mazda",model:"2021 CX-5",title:"2021 Mazda CX-5 Lug Nut Torque: Factory Range",answer:"Mazda specifies 80–108 ft·lbf (108–147 N·m) for the wheel lug nuts on the 2021 CX-5.",scope:"This exact range applies to the 2021 North American CX-5's factory wheel and stud arrangement, including the listed original 17- and 19-inch tire packages. Non-factory wheels may use different seat geometry or instructions.",detail:"Mazda publishes a range, but all five nuts on a wheel should receive the same selected final setting within it. Remove dirt from the wheel, hub and stud mounting areas, install the beveled side of each original nut toward the wheel, and do not put oil or grease on the threads or seats. Tighten in the illustrated crisscross order with a calibrated wrench.",values:[{label:"Factory torque range",value:"80–108 ft·lbf",note:"108–147 N·m"},{label:"Original tire packages",value:"17- and 19-inch",note:"Same manual torque row"},{label:"Nut orientation",value:"Beveled edge inward",note:"Factory conical seat"},{label:"Lubrication",value:"None",note:"Keep threads and seats dry"}],source:mazdaCx52021,suv:true},
  {slug:"mazda/mazda3/lug-nut-torque",keyword:"mazda 3 lug nut torque spec",make:"Mazda",model:"2020 Mazda3",title:"2020 Mazda3 Lug Nut Torque and Installation Order",answer:"Mazda specifies 80–108 ft·lbf (108–147 N·m) for the 2020 Mazda3 wheel lug nuts.",scope:"This exact range is from the 2020 Mazda3 owner procedure for its factory metric studs and wheels. Sedan and hatchback body style does not change that row, but aftermarket wheel hardware can.",detail:"Wipe dirt and grime from the hub, wheel mating face and studs. Start the original beveled nuts by hand, never oil or grease them, lower the car and tighten in the illustrated crisscross order. Choose one consistent value within the allowed range and apply it to every nut. An impact may seat the wheel provisionally, but the final pass belongs to a calibrated torque wrench.",values:[{label:"Factory torque range",value:"80–108 ft·lbf",note:"108–147 N·m"},{label:"Fastener type",value:"Metric conical-seat nut",note:"Match original configuration"},{label:"Mounting surfaces",value:"Clean",note:"Remove dirt and grime"},{label:"Final order",value:"Crisscross/star",note:"Same chosen torque at all positions"}],source:mazda32020},
  {slug:"mazda/mazda6/lug-nut-torque",keyword:"mazda 6 lug nut torque spec",make:"Mazda",model:"2021 Mazda6",title:"2021 Mazda6 Lug Nut Torque: 80–108 ft-lbf",answer:"Mazda specifies 80–108 ft·lbf (108–147 N·m) for the wheel lug nuts on the 2021 Mazda6.",scope:"This exact range applies to the 2021 U.S./Canada Mazda6 factory wheel hardware and covers the manual's original 17- and 19-inch tire rows. Accessory wheels with different nuts require their own instructions.",detail:"Clean the mounting surfaces and studs, point the beveled edge of each original nut inward, and thread every nut by hand before loading it. Mazda explicitly warns against oil or grease and against exceeding the range. Tighten across the wheel in stages, then use one chosen in-range value for the final calibrated pass at every position.",values:[{label:"Factory torque range",value:"80–108 ft·lbf",note:"108–147 N·m"},{label:"Original wheel rows",value:"17- and 19-inch",note:"Same factory fastener range"},{label:"Nut orientation",value:"Beveled edge inward",note:"Seat must match wheel"},{label:"Impact wrench",value:"Not for final torque",note:"Finish manually with calibrated wrench"}],source:mazda62021},
  {slug:"volkswagen/jetta/lug-bolt-torque",keyword:"volkswagen jetta lug nut torque spec",make:"Volkswagen",model:"2013 Jetta SportWagen",title:"2013 Volkswagen Jetta SportWagen Wheel Bolt Torque",answer:"Volkswagen's 2013 Jetta SportWagen specification book lists 120 N·m (about 89 lb-ft) for the wheel bolts on all covered vehicles.",scope:"The exact value is anchored to the North American 2013 Jetta SportWagen. Jetta sedans from other platforms or years, GLI applications, accessory wheels and stud conversions require their corresponding manual or wheel instructions.",detail:"This Volkswagen uses removable wheel bolts rather than captive studs and lug nuts. Match the bolt's thread, effective length and ball-seat geometry to the wheel, start every bolt by hand, and tighten diagonally with clean, dry hardware.",values:[{label:"2013 Jetta SportWagen",value:"120 N·m",note:"About 89 lb-ft; all vehicles in cited book"},{label:"Fastener type",value:"Wheel bolt",note:"Not a conventional lug nut"},{label:"Final pattern",value:"Diagonal/star",note:"Finish every bolt with a torque wrench"},{label:"Jetta sedan / GLI / accessory wheel",value:"Verify separately",note:"Platform and hardware may differ"}],source:vwJettaSportwagen2013},
  {slug:"volkswagen/golf/lug-bolt-torque",keyword:"volkswagen golf lug nut torque spec",make:"Volkswagen",model:"2014 Golf and GTI",title:"2014 Volkswagen Golf and GTI Wheel Bolt Torque",answer:"Volkswagen's 2014 Golf and GTI specification book lists 120 N·m (about 89 lb-ft) for the wheel bolts on all covered vehicles.",scope:"This figure is tied to the North American 2014 Golf/GTI reference. Other Golf generations, Golf R hardware, special wheel systems, accessory wheels and stud conversions must be matched to their own documentation.",detail:"Do not substitute cone-seat bolts for the production ball-seat hardware merely because the thread pitch fits. Clean the hub face, verify the wheel is flush, install every bolt by hand and complete staged diagonal passes before the final 120-N·m check.",values:[{label:"2014 Golf and GTI",value:"120 N·m",note:"About 89 lb-ft; all covered vehicles"},{label:"Hardware",value:"Correct wheel bolt",note:"Match seat, thread and effective length"},{label:"Mounting faces",value:"Clean and flush",note:"Torque cannot correct trapped corrosion"},{label:"Other Golf generation / Golf R",value:"Verify exact manual",note:"Do not generalize by model name"}],source:vwGolf2014},
  {slug:"volkswagen/passat/lug-bolt-torque",keyword:"volkswagen passat lug nut torque spec",make:"Volkswagen",model:"2014 Passat",title:"2014 Volkswagen Passat Wheel Bolt Torque: 140 N·m",answer:"Volkswagen's 2014 Passat specification book lists 140 N·m (about 103 lb-ft) for the wheel bolts on all covered vehicles.",scope:"The exact value is anchored to the North American Passat covered by the February 2014 specification book. Earlier or later Passat platforms, imported B-series variants, special wheels and non-original fasteners require their own documentation.",detail:"Do not borrow the 120-N·m Golf or Jetta figure: Volkswagen publishes 140 N·m for this Passat application. Use undamaged bolts with the correct seat and length, clean the mating surfaces, start by hand and tighten diagonally with a calibrated wrench.",values:[{label:"2014 Passat",value:"140 N·m",note:"About 103 lb-ft; all vehicles in cited book"},{label:"Golf/Jetta comparison",value:"Do not substitute 120 N·m",note:"Different documented application"},{label:"Bolt installation",value:"Hand-started, diagonal",note:"Avoid cross-threading and uneven seating"},{label:"Other Passat platform",value:"VIN/manual lookup",note:"Model name alone is insufficient"}],source:vwPassat2014},
  {slug:"volkswagen/tiguan/lug-bolt-torque",keyword:"volkswagen tiguan lug nut torque spec",make:"Volkswagen",model:"2022 Tiguan",title:"2022 Volkswagen Tiguan Wheel Bolt Torque: 140 N·m",answer:"The documented 2022 Volkswagen Tiguan owner procedure specifies 140 N·m (103 lb-ft) for wheel bolts used with steel or alloy wheels.",scope:"This exact figure and wheel-change method are anchored to the cited 2022 Tiguan manual. Earlier Tiguan platforms, another sales market, accessory wheels, locking-bolt kits and stud conversions require their corresponding instructions.",detail:"Volkswagen directs that corroded or difficult bolts be replaced, hub threads cleaned, and the bolts and hub threads kept free of oil and grease. Check the torque immediately after changing a wheel with a properly functioning torque wrench.",values:[{label:"2022 Tiguan steel or alloy wheel",value:"140 N·m",note:"103 lb-ft"},{label:"Thread condition",value:"Clean and dry",note:"Never grease or oil bolts or hub threads"},{label:"Corroded or stiff bolt",value:"Replace",note:"Clean hub threads before checking torque"},{label:"After wheel change",value:"Immediate torque check",note:"Use a functioning torque wrench"}],source:vwTiguan2022,suv:true},
  {slug:"audi/a4/wheel-bolt-torque",keyword:"audi a4 lug nut torque spec",make:"Audi",model:"A4",title:"Audi A4 Wheel Bolt Torque: 120 N·m Factory Specification",answer:"Audi's January 2020 wheel-and-tire workshop table specifies 120 N·m (about 89 lb-ft) for all listed A4 types except the early RS 4 type 8D, which is separately listed at 140 N·m.",scope:"This is a wheel-bolt specification for the original Audi wheel and correct bolt. The historical type-8D RS 4 exception, accessory wheels, changed hardware and a later superseding instruction must be handled by their own documentation.",detail:"The A4 uses removable wheel bolts, not captive studs with lug nuts. Match thread, effective length and the wheel's seat geometry. Clean the hub and wheel mating faces, start every bolt by hand, snug diagonally while raised, then lower and finish each bolt with a calibrated torque wrench. Never use the 140-N·m Q5 value just because both vehicles wear Audi wheels.",values:[{label:"A4 all listed types",value:"120 N·m",note:"About 89 lb-ft"},{label:"RS 4 type 8D exception",value:"140 N·m",note:"About 103 lb-ft; separate early application"},{label:"Fastener",value:"Wheel bolt",note:"Correct seat and effective length required"},{label:"Final pattern",value:"Diagonal/crisscross",note:"Check every bolt with torque wrench"}],source:audiWheelSpecs2020},
  {slug:"audi/a6/wheel-bolt-torque",keyword:"audi a6 lug nut torque spec",make:"Audi",model:"A6",title:"Audi A6 Wheel Bolt Torque: 120 N·m for Standard Models",answer:"Audi's January 2020 wheel-and-tire reference specifies 120 N·m (about 89 lb-ft) for all listed A6 types. It separately lists 140 N·m for A6 PAX wheels and security versions, so those are not interchangeable rows.",scope:"Use 120 N·m only with a standard A6 factory wheel and its correct bolts. PAX, security, accessory, altered and special-purpose wheel systems require their own listed value and hardware.",detail:"Identify the wheel system before reaching for the wrench. A bolt can share the thread diameter yet have the wrong ball-seat radius or shank length. With clean, flush mounting faces, start the proper bolts by hand, tighten across the wheel in stages and make the final pass with a calibrated torque wrench. Recheck any replacement-wheel instructions that supersede the vehicle value.",values:[{label:"Standard A6, all listed types",value:"120 N·m",note:"About 89 lb-ft"},{label:"A6 PAX wheels",value:"140 N·m",note:"About 103 lb-ft; special wheel system"},{label:"A6 security model",value:"140 N·m",note:"Special application"},{label:"Hardware check",value:"Seat + length + thread",note:"All must match the wheel"}],source:audiWheelSpecs2020},
  {slug:"audi/q5/wheel-bolt-torque",keyword:"audi q5 lug nut torque spec",make:"Audi",model:"Q5",title:"Audi Q5 Wheel Bolt Torque: 140 N·m Factory Specification",answer:"Audi's January 2020 workshop table specifies 140 N·m (about 103 lb-ft) for all listed Q5 types.",scope:"The value applies to the Q5 row with factory-approved wheels and the correct original-style bolts. Accessory wheels, nonstandard bolts or a later model-specific instruction can supersede it; confirm the VIN guide when the hardware history is unknown.",detail:"Do not borrow the A4/A6 120-N·m figure—the Q5 is explicitly listed at 140 N·m. Remove loose corrosion from the hub and wheel mating surfaces, verify bolt seat and effective length, start bolts by hand and snug in a diagonal pattern. Lower the vehicle enough to prevent rotation, then check every bolt at the final setting with a calibrated wrench.",values:[{label:"Q5, all listed types",value:"140 N·m",note:"About 103 lb-ft"},{label:"A4/A6 comparison",value:"120 N·m",note:"Do not transfer passenger-car row"},{label:"Bolt selection",value:"Correct seat and length",note:"Torque cannot fix mismatched hardware"},{label:"Final verification",value:"Every bolt",note:"Calibrated torque wrench"}],source:audiWheelSpecs2020,suv:true},
  {slug:"bmw/3-series/wheel-bolt-torque",keyword:"bmw 3 series lug nut torque spec",make:"BMW",model:"2018 3 Series",title:"2018 BMW 3 Series Wheel Bolt Torque: 140 N·m",answer:"The documented 2018 BMW 3 Series owner procedure specifies 140 N·m (about 103 lb-ft) for the wheel bolts.",scope:"The exact value is anchored to the covered 2018 3 Series manual. Earlier E-chassis models, later G20 variants, M3 applications, accessory wheels, locking kits and stud conversions require their corresponding instructions.",detail:"BMW uses removable wheel bolts, not ordinary lug nuts. Clean the mounting faces and bolts, install at least two opposite bolts finger-tight to center the wheel, fit the remaining bolts, and tighten diagonally. Verify secure seating with a calibrated torque wrench.",values:[{label:"2018 3 Series",value:"140 N·m",note:"About 103 lb-ft"},{label:"Tightening pattern",value:"Diagonal/crosswise",note:"Center the wheel with opposite bolts"},{label:"Final verification",value:"Calibrated torque wrench",note:"Check secure seating"},{label:"Other chassis or M3",value:"Verify separately",note:"Use VIN-based BMW Driver's Guide"}],source:bmw3Series2018},
  {slug:"bmw/5-series/wheel-bolt-torque",keyword:"bmw 5 series lug nut torque spec",make:"BMW",model:"2022 5 Series",title:"2022 BMW 5 Series Wheel Bolt Torque: 140 N·m",answer:"The documented 2022 BMW 5 Series owner procedure specifies 140 N·m (about 103 lb-ft) for the wheel bolts after mounting a replacement or emergency wheel.",scope:"This exact value and method are anchored to the covered 2022 5 Series. Earlier E39/E60/F10 generations, M5 hardware, accessory wheels, locking bolts and non-original fasteners require their exact documentation.",detail:"Hand-start the correct bolts and tighten crosswise so the wheel centers evenly. After final torque, check tire pressure, reset or reinitialize the tire-monitoring system as required, and confirm bolt seating with a calibrated torque wrench.",values:[{label:"2022 5 Series",value:"140 N·m",note:"About 103 lb-ft"},{label:"Installation order",value:"Crosswise",note:"Hand-start matching wheel bolts"},{label:"After installation",value:"Pressure + monitor reset",note:"Follow exact TPM/RPA procedure"},{label:"Earlier chassis / M5 / accessory wheel",value:"Verify separately",note:"Hardware and instructions may differ"}],source:bmw5Series2022},
  {slug:"bmw/x5/wheel-bolt-torque",keyword:"bmw x5 lug nut torque spec",make:"BMW",model:"2019 G05 X5",title:"2019 BMW G05 X5 Wheel Bolt Torque: 140 N·m",answer:"BMW's repair instruction for the affected 2019 G05 X5 specifies 140 N·m (about 103 lb-ft) for the wheel bolts.",scope:"The numerical value and crosswise procedure are anchored to the 2019 G05 X5 listed in BMW Recall Campaign 19V-541. Earlier E53/E70/F15 X5 generations, X5 M, accessory wheels and changed fasteners require their own BMW or wheel-maker instructions.",detail:"BMW directs technicians to screw in and hand-tighten all bolts evenly in a crosswise order to center the rim, then use a calibrated torque wrench at 140 N·m. Check every bolt again in the same order after the final pass.",values:[{label:"2019 G05 X5",value:"140 N·m",note:"About 103 lb-ft"},{label:"Initial seating",value:"Hand-tight, crosswise",note:"Center rim evenly"},{label:"Final tool",value:"Calibrated torque wrench",note:"Crosswise at prescribed value"},{label:"Confirmation",value:"Check same order again",note:"BMW campaign procedure"}],source:bmwX5G05Recall,suv:true},
  {slug:"mercedes-benz/c-class/wheel-bolt-torque",keyword:"mercedes c class lug nut torque spec",make:"Mercedes-Benz",model:"2020 C-Class Sedan",title:"2020 Mercedes C-Class Wheel Bolt Torque: 130 N·m",answer:"The 2020 Mercedes-Benz C-Class Sedan operator's manual specifies a final wheel-bolt torque of 130 N·m (96 lb-ft). It directs a preliminary diagonal pass at no more than 80 N·m before the final pass.",scope:"This exact two-stage procedure applies to the standard 2020 U.S.-market C-Class Sedan manual. AMG vehicles, another body style or model year, accessory wheels and changed fasteners must follow their own operator's manual or approved-wheel instructions.",detail:"Use approved wheel bolts with the correct seat and effective length, keep the threads free of oil and grease, and start each bolt by hand. With the vehicle on the ground, tighten positions 1 through 5 diagonally to no more than 80 N·m, then repeat the same order at 130 N·m. Check tire pressure and restart the applicable pressure-loss or TPMS procedure after installation.",values:[{label:"Final wheel-bolt torque",value:"130 N·m",note:"96 lb-ft"},{label:"Preliminary diagonal pass",value:"Maximum 80 N·m",note:"59 lb-ft"},{label:"Final order",value:"1–5 diagonal pattern",note:"Repeat at full torque"},{label:"Thread treatment",value:"No oil or grease",note:"Use approved undamaged bolts"}],source:mercedesCClass2020},
  {slug:"mercedes-benz/e-class/wheel-bolt-torque",keyword:"mercedes e class lug nut torque spec",make:"Mercedes-Benz",model:"2020 E-Class Coupe",title:"2020 Mercedes E-Class Coupe Wheel Bolt Torque: 150 N·m",answer:"The 2020 Mercedes-Benz E-Class Coupe operator's manual specifies 150 N·m (111 lb-ft) for the final wheel-bolt pass—not the 130 N·m commonly quoted for some other Mercedes passenger cars.",scope:"This exact value and method are for the U.S.-market 2020 E-Class Coupe manual. Sedan, wagon, cabriolet, AMG, accessory-wheel and other model-year applications require their corresponding document; the E-Class name alone is not enough.",detail:"Use only approved bolts that match the wheel. Keep bolt and hub threads clean and dry, start them by hand, and lower the vehicle before final tightening. Mercedes specifies a diagonal 1–5 pass capped at 80 N·m, followed by the same diagonal order at 150 N·m. Adjust tire pressure and restart the relevant monitoring system afterward.",values:[{label:"Final wheel-bolt torque",value:"150 N·m",note:"111 lb-ft"},{label:"Preliminary diagonal pass",value:"Maximum 80 N·m",note:"59 lb-ft"},{label:"Tightening sequence",value:"1–5 diagonal",note:"Vehicle supported on ground for final torque"},{label:"C-Class comparison",value:"Do not substitute 130 N·m",note:"Model/body procedure differs"}],source:mercedesEClassCoupe2020},
  {slug:"mercedes-benz/glc/wheel-bolt-torque",keyword:"mercedes glc lug nut torque spec",make:"Mercedes-Benz",model:"2019 GLC SUV",title:"2019 Mercedes GLC Wheel Bolt Torque: 150 N·m",answer:"Mercedes-Benz specifies 150 N·m (111 lb-ft) for the 2019 GLC SUV wheel bolts. The operator's manual calls for an even crosswise sequence and an immediate torque check after a wheel change.",scope:"This exact figure comes from the U.S. 2019 GLC SUV operator's manual. It should not be transferred automatically to a later redesigned GLC, an AMG supplement, a coupe, an accessory wheel or non-original fasteners.",detail:"Lower the vehicle until it stands firmly on the ground, then tighten all five approved wheel bolts evenly in the illustrated crosswise order at 150 N·m. Check the newly installed tire's pressure and correct it if needed. If bolt threads, hub threads or seating surfaces are damaged, stop and have them repaired; extra torque cannot make mismatched or damaged hardware safe.",values:[{label:"Final wheel-bolt torque",value:"150 N·m",note:"111 lb-ft"},{label:"Tightening order",value:"Crosswise",note:"Five-bolt illustrated sequence"},{label:"After wheel change",value:"Immediate torque check",note:"Manual safety instruction"},{label:"After installation",value:"Check tire pressure",note:"Restart monitoring when applicable"}],source:mercedesGlc2019,suv:true},
];

const researchedLugEditorial:Record<string,{sections:SpecRecord["sections"];faqs:SpecRecord["faqs"]}>={
  "volkswagen/jetta/lug-bolt-torque":{sections:[
    {heading:"What the 2013 Jetta SportWagen specification covers",paragraphs:["Volkswagen Group of America's quick-reference book lists 120 N·m for wheel bolts to the hub on every Jetta SportWagen vehicle covered by that publication. Rounded to imperial units, that is about 89 lb-ft.","The scope matters because the Jetta name continued across different platforms and body styles. Confirm the VIN and manual before carrying this SportWagen value to a later sedan, GLI or wheel package."]},
    {heading:"Wheel-bolt identity matters as much as torque",paragraphs:["A Volkswagen wheel bolt combines thread size, usable shank length and a seat profile matched to the wheel. A cone-seat aftermarket bolt can thread into the hub yet contact an original ball-seat wheel incorrectly, leaving the wheel unsafe even when the wrench reaches 120 N·m.","Compare any locking bolt with the standard bolts and make sure its adapter is fully engaged. A stud conversion or spacer kit replaces the production hardware rules with the supplier's engagement and torque instructions."]},
    {heading:"A repeatable Jetta installation method",paragraphs:["Remove loose corrosion and debris from the hub face and wheel mounting pad without oiling the bolt threads or seats. Hang the wheel flush, start all five bolts by hand and snug them in an opposite-side pattern while the wheel is lightly supported.","Lower the vehicle enough to prevent rotation, then repeat the diagonal order at 120 N·m with a calibrated wrench. If a bolt binds before its seat contacts the wheel, stop and inspect the threads rather than forcing it home with an impact."]},
  ],faqs:[{q:"What is the 2013 Volkswagen Jetta SportWagen wheel-bolt torque?",a:"The cited Volkswagen specification book lists 120 N·m, approximately 89 lb-ft."},{q:"Does a Jetta use lug nuts or wheel bolts?",a:"The covered factory arrangement uses removable wheel bolts that thread directly into the hub."},{q:"Can 120 N·m be used on every Volkswagen Jetta?",a:"No. Confirm the body style, platform, model year and wheel hardware in the exact vehicle manual."},{q:"Can I lubricate Jetta wheel bolts before torquing them?",a:"Do not add lubricant to a dry-thread specification. Use clean, dry production hardware unless an approved replacement system explicitly directs otherwise."}]},
  "volkswagen/golf/lug-bolt-torque":{sections:[
    {heading:"The 2014 Golf and GTI factory value",paragraphs:["Volkswagen's North American quick-reference book assigns 120 N·m to wheel bolts for all Golf and GTI vehicles covered by the 2014 publication. That converts to approximately 89 lb-ft.","The word “all” belongs to that document's application set, not every Golf ever built. A later Golf R, Mk8 vehicle, accessory wheel or non-original fastener still needs its own confirmation."]},
    {heading:"Seat shape and effective bolt length",paragraphs:["Original Volkswagen wheels commonly use a radiused ball seat. Many aftermarket wheels use a cone seat, so matching only the M14 thread is not enough. The bolt must center the wheel on the intended seat without bottoming in the hub or losing required thread engagement.","Spacers require longer approved bolts or a documented stud system. Never stack a spacer behind a factory wheel and assume that the original bolts remain long enough."]},
    {heading:"How to reach 120 N·m evenly",paragraphs:["Clean the hub flange and wheel mounting face so the wheel can sit flat. Install each bolt several turns by hand, snug lightly in a star pattern, and rotate the wheel if necessary to confirm it is centered before vehicle weight is applied.","Make the final diagonal pass at 120 N·m with a calibrated torque wrench. Do not use an impact gun for the final value; impact energy can overshoot before the operator recognizes that the bolt has seated."]},
  ],faqs:[{q:"What is the 2014 Volkswagen Golf wheel-bolt torque?",a:"The Volkswagen Golf and GTI specification book lists 120 N·m, about 89 lb-ft."},{q:"Does the same value cover the 2014 GTI?",a:"Yes. The cited book states 120 N·m for all Golf and GTI vehicles in its covered application set."},{q:"Can cone-seat bolts be used on original Golf wheels?",a:"Not unless the wheel manufacturer specifies that seat. The bolt seat, length and thread must all match the installed wheel."},{q:"Does a wheel spacer change bolt requirements?",a:"Yes. Use the spacer or conversion-kit maker's required bolt length, engagement and tightening instructions."}]},
  "volkswagen/passat/lug-bolt-torque":{sections:[
    {heading:"Why this Passat uses 140 N·m",paragraphs:["The February 2014 Volkswagen Passat quick-reference book explicitly lists 140 N·m for wheel bolts to the hub on all vehicles it covers. That is approximately 103 lb-ft and corrects the often-repeated 120-N·m passenger-car shortcut.","Volkswagen model names do not guarantee identical wheel fasteners. The North American Passat platform represented here must be separated from Golf/Jetta applications and from European or later Passat generations."]},
    {heading:"Do not solve a loose wheel with extra torque",paragraphs:["Correct clamping starts with a clean, flat hub-to-wheel joint and bolts that match the wheel seats. Rust scale, a bent wheel, wrong bolt radius or insufficient engagement can allow movement even when the wrench clicks at 140 N·m.","If a wheel repeatedly loosens, inspect the bolt seats, hub threads, wheel mounting face and runout. Raising the setting above Volkswagen's value can stretch hardware or damage threads without repairing the fault."]},
    {heading:"Passat wheel installation sequence",paragraphs:["Start all five correct bolts by hand. Snug them in a star pattern while the wheel remains centered, then lower the car only enough to prevent rotation so the wheel is not pulled crooked under full vehicle weight.","Complete the same diagonal order at 140 N·m using a calibrated torque wrench. Confirm every position once; do not keep pulling on a click wrench repeatedly after it signals the setting."]},
  ],faqs:[{q:"What is the 2014 Volkswagen Passat wheel-bolt torque?",a:"Volkswagen lists 140 N·m, approximately 103 lb-ft, for all Passat vehicles covered by the cited 2014 book."},{q:"Can I use the Golf or Jetta 120-N·m value on this Passat?",a:"No. Volkswagen publishes a separate 140-N·m value for the covered Passat application."},{q:"Why might a correctly torqued Passat wheel still loosen?",a:"Incorrect bolt seats, inadequate thread engagement, corrosion, a damaged wheel or an unseated mounting face can prevent proper clamping."},{q:"Does this Passat chart cover every model year worldwide?",a:"No. It is anchored to the North American 2014 specification book; verify other generations and markets separately."}]},
  "volkswagen/tiguan/lug-bolt-torque":{sections:[
    {heading:"The documented 2022 Tiguan specification",paragraphs:["Volkswagen's wheel-change section specifies 140 N·m (103 lb-ft) for the wheel bolts with either steel or alloy wheels in the covered 2022 Tiguan manual. Wheel diameter is not offered as a reason to change that value.","Earlier Tiguan platforms and other markets can have different service data, so retain the model-year and manual boundary when quoting the figure. An accessory wheel's approved instructions can also supersede the production procedure."]},
    {heading:"Volkswagen's dry-thread warning",paragraphs:["The manual explicitly says never to grease or oil the wheel bolts or hub threads. Lubrication lowers friction, so a wrench set to the dry value can produce excessive bolt tension even though its display looks correct.","A corroded or difficult-to-turn bolt must be replaced, and contaminated hub threads must be cleaned before torque is checked. Do not use the 140-N·m final pass to force a stiff fastener through damaged threads."]},
    {heading:"Checks immediately after changing a wheel",paragraphs:["Mount the wheel flush, start every bolt by hand and tighten opposite positions in stages. Use the anti-theft bolt only in the location required by the wheel cover, where applicable, and make sure the key seats fully before applying torque.","Volkswagen directs an immediate check with a properly functioning torque wrench after the wheel change. Correct tire pressure and complete the exact vehicle's pressure-monitoring reset or relearn when required."]},
  ],faqs:[{q:"What is the documented 2022 Volkswagen Tiguan wheel-bolt torque?",a:"The cited owner procedure specifies 140 N·m, or 103 lb-ft, for steel or alloy wheels."},{q:"Can Tiguan wheel bolts be greased?",a:"No. Volkswagen explicitly instructs that the bolts and hub threads must not be greased or oiled."},{q:"What should I do with a corroded or stiff Tiguan wheel bolt?",a:"Replace the bolt and clean the hub threads before checking final torque."},{q:"When should Tiguan wheel-bolt torque be checked?",a:"The covered manual calls for a torque-wrench check immediately after changing a wheel."}]},
  "bmw/3-series/wheel-bolt-torque":{sections:[
    {heading:"The covered 2018 BMW 3 Series value",paragraphs:["The 2018 owner procedure assigns 140 N·m—approximately 103 lb-ft—to the wheel bolts. The value belongs with original-style BMW wheels and matching bolts on the documented model-year application.","A 3 Series badge alone is not enough to cover decades of E, F and G chassis. Confirm the VIN-based Driver's Guide when the car is another year, an M3, or equipped with accessory wheels."]},
    {heading:"Centering a BMW wheel before final torque",paragraphs:["Clean mud, rust scale and debris from the wheel and hub mounting faces. Position the wheel squarely and screw at least two bolts finger-tight into opposite holes before installing the remaining bolts; this supports the rim evenly while it centers.","Snug all five crosswise, lower the vehicle and complete the diagonal pass at 140 N·m. A calibrated wrench—not the impact gun used for removal—controls the final clamp load."]},
    {heading:"Bolt seat, length and thread condition",paragraphs:["BMW wheel bolts must match the wheel's seat profile and effective length. An aftermarket wheel may require its own bolts even when the production bolts appear to fit, while spacers or stud conversions change required thread engagement.","Replace damaged or severely corroded hardware. Do not compensate for a mismatched seat, binding thread or wheel that will not sit flush by applying more than the specified torque."]},
  ],faqs:[{q:"What is the 2018 BMW 3 Series wheel-bolt torque?",a:"The covered owner procedure specifies 140 N·m, approximately 103 lb-ft."},{q:"Does a BMW 3 Series use lug nuts?",a:"The documented factory arrangement uses removable wheel bolts that screw directly into the hub."},{q:"Can 140 N·m be used on every 3 Series generation?",a:"No. Confirm the chassis, model year, M/non-M application and installed wheel instructions."},{q:"Can an impact wrench provide final BMW wheel torque?",a:"Use it only for controlled preliminary work if appropriate; the final crosswise pass should be made with a calibrated torque wrench."}]},
  "bmw/5-series/wheel-bolt-torque":{sections:[
    {heading:"The 2022 BMW 5 Series owner-manual specification",paragraphs:["After mounting the replacement or emergency wheel, the documented procedure calls for a crosswise wheel-bolt pass at 140 N·m, about 103 lb-ft. The crosswise order is part of the instruction because it seats the rim evenly against the hub.","This page deliberately names 2022 rather than blending E39, E60, F10 and G30-era information. Earlier chassis, M5 models and non-original wheel packages must be checked against their own BMW or wheel-maker documentation."]},
    {heading:"Wheel installation and follow-up checks",paragraphs:["Start every correct bolt by hand and tighten across the wheel progressively. If the wheel does not rest uniformly against the hub or a bolt feels rough, remove it and correct the mounting or thread problem before final torque.","After the 140-N·m pass, check tire pressure and reset or reinitialize the applicable tire monitor. The manual also calls for confirming bolt seating with a calibrated torque wrench."]},
    {heading:"Non-original wheels and locking bolts",paragraphs:["Aftermarket light-alloy wheels may require bolts supplied with the wheel because seat geometry and usable shank length can differ from BMW production hardware. Follow those approved instructions rather than mixing fasteners based only on thread diameter.","Push the locking-bolt key fully into its pattern and keep it square while applying torque. A damaged key or partially engaged lock can slip before the bolt reaches the setting."]},
  ],faqs:[{q:"What is the 2022 BMW 5 Series wheel-bolt torque?",a:"BMW's covered 2022 5 Series procedure specifies a crosswise final setting of 140 N·m, approximately 103 lb-ft."},{q:"How should 5 Series wheel bolts be tightened?",a:"Start them by hand and tighten crosswise so the wheel centers and seats evenly."},{q:"What should be checked after changing a BMW 5 Series wheel?",a:"Confirm bolt seating with a calibrated wrench, correct tire pressure and reset or reinitialize the applicable tire monitor."},{q:"Do aftermarket 5 Series wheels use the factory bolts?",a:"Not automatically. Use the wheel maker's specified bolt seat, length, engagement and torque procedure."}]},
  "bmw/x5/wheel-bolt-torque":{sections:[
    {heading:"BMW's exact 2019 G05 X5 repair instruction",paragraphs:["Recall Campaign 19V-541 identifies the G05 X5 and directs a final wheel-bolt torque of 140 N·m, about 103 lb-ft. BMW specifies a calibrated torque wrench and a crosswise sequence, then instructs the technician to check every bolt again in the same order.","The campaign covered a small production population with left-side bolt concerns, but its repair instruction provides an application-specific G05 torque and method. It does not establish the value for every earlier X5 chassis."]},
    {heading:"Two crosswise operations with different purposes",paragraphs:["First screw in all five bolts and tighten them evenly by hand in a crosswise order. This centers the rim and lets the technician detect a bolt that binds before its seat contacts the wheel.","Then apply 140 N·m crosswise with the calibrated wrench. Repeat the same order as a confirmation check; do not keep pulling past the wrench signal once the prescribed torque has been reached."]},
    {heading:"When this G05 chart does not apply",paragraphs:["E53, E70 and F15 X5 generations, X5 M hardware, accessory wheels and stud-conversion kits require their own instructions. Wheel diameter by itself does not prove the bolt seat, length or specified clamp load.","If any bolt or hub thread is damaged, replace or repair it using BMW-approved information. Extra torque cannot make a cross-threaded bolt, wrong seat or partially seated wheel safe."]},
  ],faqs:[{q:"What is the 2019 BMW G05 X5 wheel-bolt torque?",a:"BMW's recall repair instruction specifies 140 N·m, approximately 103 lb-ft."},{q:"What tightening order does BMW specify for the G05 X5?",a:"Hand-tighten evenly in a crosswise sequence, torque crosswise with a calibrated wrench, then check all bolts again in the same order."},{q:"Does this chart cover every BMW X5 generation?",a:"No. It is anchored to the 2019 G05; earlier chassis, X5 M and accessory wheels require exact documentation."},{q:"Can extra torque repair a loose or damaged X5 wheel joint?",a:"No. Inspect bolt seats, threads, mounting faces and the wheel itself instead of exceeding BMW's specification."}]},
};

function lugPage(j: LugJob): SpecRecord {
  const base: Base = {slug:j.slug,keyword:j.keyword,make:j.make,model:j.model,category:"Torque Specs",title:j.title,
    metaDescription:`${j.title} with year and generation cautions, dry-thread guidance, tightening pattern, recheck procedure and official manual lookup.`,
    answer:j.answer,scope:j.scope,detail:j.detail,values:j.values,sources:[j.source],identity:j.model,
    distinctions:[j.scope,j.detail],featureImage:j.suv?lugSuv:lugSedan,featureOverlay:true};
  const record=lugGuide(base);
  const editorial=researchedLugEditorial[j.slug];
  if(editorial){record.sections.unshift(...editorial.sections);record.faqs=editorial.faqs;record.intro=[record.answer,record.scope,record.detail];}
  return record;
}

type TorqueJob = {slug:string;keyword:string;make:string;model:string;title:string;answer:string;scope:string;detail:string;values:SpecValue[];source:Source;diagram?:Diagram["type"]};

const torqueJobs: TorqueJob[] = [
  {slug:"ford/302/head-bolt-torque-sequence",keyword:"ford 302 head bolt torque sequence",make:"Ford",model:"1996 F-150 5.0L/302 V8",title:"Ford 302 Head Bolt Torque Sequence and Application Guide",answer:"For the covered 1996 F-150 5.0L, non-flanged standard bolts use 55–65 then 65–72 lb-ft; flanged torque-to-yield bolts use 25–35 lb-ft, 45–55 lb-ft, then 85–95°. Never mix the two bolt styles on one head.",scope:"The dual procedure applies to Ford's documented 5.0L truck service population and bolt identification. Earlier 289/302 builds, aluminum heads and aftermarket studs require their exact instructions.",detail:"Ford states that the flanged TTY bolts are single-use. Identify every bolt before assembly and keep one uniform style on each cylinder head.",values:[{label:"Standard non-flanged pass 1",value:"55–65 lb-ft",note:"75–88 N·m"},{label:"Standard non-flanged final",value:"65–72 lb-ft",note:"88–98 N·m"},{label:"Flanged TTY pass 1",value:"25–35 lb-ft",note:"34–47 N·m; new bolts"},{label:"Flanged TTY pass 2",value:"45–55 lb-ft",note:"61–75 N·m"},{label:"Flanged TTY final",value:"85–95°",note:"Additional 1/4 turn"}],source:source("Ford TSB 95-3-10 — 5.0L cylinder-head bolt identification", "https://charm.li/Ford/1995/F%20150%202WD%20Pickup%20V8-302%205.0L/Repair%20and%20Diagnosis/Technical%20Service%20Bulletins/All%20Technical%20Service%20Bulletins/New%20Cylinder%20Head%20Bolt%20-%20Service%20Tips/", "Ford service bulletin distinguishing standard and TTY bolt styles, prohibiting mixed sets, and specifying both tightening procedures and TTY replacement."),diagram:"head"},
  {slug:"ford/351-windsor/head-bolt-torque-sequence",keyword:"ford 351 windsor head bolt torque sequence",make:"Ford",model:"1993 F-150 5.8L/351W V8",title:"Ford 351 Windsor Head Bolt Torque Sequence Guide",answer:"For the covered 1993 F-150 5.8L/351 Windsor, tighten the head bolts in sequence to 85 lb-ft, then 95 lb-ft, and finally 105–112 lb-ft.",scope:"The numerical stages apply to the documented 1993 truck 351W with production-style iron heads and bolts. 351 Cleveland, 351M/400, aluminum heads and stud kits are separate applications.",detail:"Complete every Ford sequence pass before increasing torque. Do not substitute the lower 5.0L/302 values merely because both engines belong to the Windsor family.",values:[{label:"Pass 1",value:"85 lb-ft",note:"115 N·m"},{label:"Pass 2",value:"95 lb-ft",note:"129 N·m"},{label:"Final pass",value:"105–112 lb-ft",note:"143–151 N·m"},{label:"Other 351 families",value:"Different procedure",note:"Identify 351W first"}],source:source("1993 Ford F-150 factory service data — 5.8L/351W torque specifications", "https://charm.li/Ford/1993/F%20150%202WD%20Pickup%20V8-351%205.8L/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Specifications/Torque%20Specifications/", "Factory-service-data transcription specifying 85, 95 and 105–112 lb-ft head-bolt passes for the covered 5.8L Windsor truck engine."),diagram:"head"},
  {slug:"chevrolet/5-3/head-bolt-torque-sequence",keyword:"chevy 5.3 head bolt torque sequence",make:"Chevrolet",model:"2005 Silverado 5.3L VIN Z V8",title:"Chevy 5.3 Head Bolt Torque Sequence by Engine Generation",answer:"For the covered 2005 Silverado 5.3L VIN Z, install new bolts; tighten M11 bolts 1–10 to 22 lb-ft, then 90°, then 70°. Tighten M8 bolts 11–15 to 22 lb-ft from the center outward.",scope:"This chart is for the documented 2005 Gen III 5.3L VIN Z application. First-design long/medium-bolt engines, later Gen IV and Gen V EcoTec3 engines, and aftermarket studs require their own procedures.",detail:"Use an angle meter and the factory numbered sequence. Bolt length and block design must be established before parts are ordered or angles are applied.",values:[{label:"M11 pass 1 — bolts 1–10",value:"22 lb-ft",note:"30 N·m; new bolts"},{label:"M11 pass 2",value:"90°",note:"Exact sequence"},{label:"M11 final",value:"70°",note:"Covered second-design procedure"},{label:"M8 bolts 11–15",value:"22 lb-ft",note:"30 N·m; center outward"}],source:source("2005 Chevrolet Silverado 5.3L factory service data — cylinder head", "https://charm.li/Chevrolet/2005/Silverado%201500%204WD%20V8-5.3L%20VIN%20Z%20Flex%20Fuel/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Cylinder%20Head%20Assembly/Specifications/", "Factory-service-data transcription requiring new bolts and specifying M11 stages of 22 lb-ft, 90° and 70°, plus 22 lb-ft for the M8 group."),diagram:"head"},
  {slug:"chevrolet/350/rocker-arm-torque",keyword:"chevy 350 rocker arm torque specs",make:"Chevrolet",model:"Chevrolet Performance 350 with Self-Aligning Roller Rockers",title:"Chevy 350 Rocker Arm Adjustment and Poly-Lock Torque",answer:"For Chevrolet Performance's covered self-aligning aluminum roller-rocker kit, set each hydraulic lifter at zero lash on the cam base circle, then turn the adjusting nut another 1/2 to 1 turn. Hold the nut and tighten the internal set screw to 15–20 lb-ft before locking both together no more than another 1/4 turn.",scope:"This procedure applies to the documented Chevrolet Performance self-aligning roller rocker and poly-lock arrangement on compatible small-block heads. Stock stamped rockers, solid lifters, stud girdles, pedestal conversions and other roller kits use their own instructions.",detail:"Confirm the pushrod is seated in the lifter and rocker cup and the valve tip is centered under the self-aligning roller. Chevrolet requires at least 0.040 in rocker-to-retainer clearance, 0.020 in nut-to-rocker clearance and 0.040 in pushrod-to-head clearance throughout the complete motion.",values:[{label:"Hydraulic-lifter preload",value:"Zero lash + 1/2–1 turn",note:"Lifter must be on cam base circle"},{label:"Poly-lock set screw",value:"15–20 lb-ft",note:"Hold adjusting nut stationary"},{label:"Final locking movement",value:"1/4 turn maximum",note:"Nut and set screw together"},{label:"Rocker/retainer and pushrod clearance",value:"0.040 in minimum",note:"Check throughout full lift"},{label:"Nut-to-rocker clearance",value:"0.020 in minimum",note:"Check valve open and closed"}],source:source("Chevrolet Performance self-aligning aluminum rocker-arm instructions", "https://www.chevrolet.com/content/dam/chevrolet/na/us/english/index/performance/resources/installation-guides/crate-engines/01-images/small-block-self-aligning-aluminum-rocker-arms.pdf", "Primary Chevrolet Performance instructions specifying zero lash plus 1/2–1 turn, 15–20-lb-ft set-screw torque and required valvetrain clearances."),diagram:"valve"},
  {slug:"chevrolet/350/flywheel-bolt-torque",keyword:"chevy 350 flywheel torque specs",make:"Chevrolet",model:"Chevrolet Performance 350/290 HP V8",title:"Chevrolet Performance 350 Flywheel Bolt Torque",answer:"Chevrolet Performance specifies 65–70 lb-ft (88–95 N·m) for the flywheel bolts on its covered 350/290 HP long-block package.",scope:"The range is tied to Chevrolet Performance 350/290 HP engine package 19172591 and matching production-style components. A different crankshaft flange, flywheel, bolt kit, rear-main-seal design or racing assembly requires its corresponding documentation.",detail:"Verify the correct flywheel balance, tooth count, pilot support and bolt length before assembly. Clean the crank flange and flywheel face, use only the specified thread treatment and tighten progressively in a crossing pattern; bolt torque cannot correct a mismatched balance weight or excessive runout.",values:[{label:"Flywheel to crankshaft",value:"65–70 lb-ft",note:"88–95 N·m; covered Chevrolet Performance package"},{label:"Pressure plate to flywheel",value:"Separate specification",note:"Do not transfer crank-bolt value"},{label:"Balance and rear-main-seal design",value:"Must match",note:"One- and two-piece-seal parts differ"},{label:"Aftermarket fastener kit",value:"Bolt-maker instructions",note:"Lubricant changes clamp load"}],source:source("Chevrolet Performance 350/290 HP long-block specifications", "https://www.chevrolet.com/content/dam/chevrolet/na/us/english/index/performance/resources/installation-guides/crate-engines/02-pdf/350-290-hp-long-block-crate-engine-19172591.pdf", "Primary Chevrolet Performance guide listing 65–70 lb-ft for flywheel bolts on the covered 350/290 HP engine."),diagram:"main"},
  {slug:"chevrolet/350/flexplate-bolt-torque",keyword:"chevy 350 flexplate torque specs",make:"Chevrolet",model:"1988 C1500 5.7L/350 V8 Automatic",title:"1988 Chevy 350 Flexplate Bolt Torque Specs",answer:"For the covered 1988 Chevrolet C1500 5.7L/350 automatic, tighten the flexplate-to-crankshaft bolts to 75 lb-ft (100 N·m). Tighten the separate flexplate-to-torque-converter bolts to 50 lb-ft (65 N·m).",scope:"The two values apply to the documented 1988 C1500 350 and production automatic-transmission joints. Other model years, one-piece rear-main-seal conversions, different converters, aftermarket plates and performance bolts require their exact procedures.",detail:"The crank bolts and converter bolts are physically close but clamp different joints. Confirm flexplate offset, balance weight, tooth count and converter pattern, inspect the ring gear, and tighten each group progressively; a backward or mismatched plate cannot be corrected with torque.",values:[{label:"Flexplate to crankshaft",value:"75 lb-ft",note:"100 N·m"},{label:"Flexplate to torque converter",value:"50 lb-ft",note:"65 N·m; separate joint"},{label:"Flexplate orientation",value:"Application-specific",note:"Check offset and balance weight"},{label:"Ring gear and converter pattern",value:"Inspect and match",note:"Before final tightening"}],source:source("1988 Chevrolet C1500 350 flexplate tightening specifications", "https://charm.li/Chevrolet/1988/C%201500%20Truck%202WD%20V8-350%205.7L/Repair%20and%20Diagnosis/Transmission%20and%20Drivetrain/Flex%20Plate/Specifications/Tightening%20Specifications/", "Factory-service-data transcription listing 75 lb-ft for flexplate-to-crankshaft bolts and 50 lb-ft for flexplate-to-converter fasteners."),diagram:"main"},
  {slug:"chevrolet/350/harmonic-balancer-bolt-torque",keyword:"chevy 350 harmonic balancer torque spec",make:"Chevrolet",model:"Chevrolet Performance 350/290 HP V8",title:"Chevrolet Performance 350 Harmonic Balancer Bolt Torque",answer:"Chevrolet Performance specifies 63 lb-ft (85 N·m) for the crankshaft-balancer retaining bolt on its covered 350/290 HP long-block package. The separate balancer-pulley bolts use 35 lb-ft (47 N·m).",scope:"These values apply to Chevrolet Performance 350/290 package 19172591 with its intended threaded crank snout, damper and hardware. Early press-fit arrangements, production engines with different charts, aftermarket dampers and reusable performance bolts require separate instructions.",detail:"Align the key and seat the balancer with a dedicated installer before applying the retaining-bolt torque. Never hammer the damper or use the final bolt to draw the hub from the end of the crankshaft; inspect the hub bore, keyway and elastomer if installation force is abnormal.",values:[{label:"Crankshaft balancer retaining bolt",value:"63 lb-ft",note:"85 N·m; covered Chevrolet Performance engine"},{label:"Balancer pulley bolts",value:"35 lb-ft",note:"47 N·m; separate fastener group"},{label:"Damper installation",value:"Dedicated installer",note:"Seat before retaining-bolt torque"},{label:"Aftermarket damper or bolt",value:"Manufacturer procedure",note:"Washer and lubricant may differ"}],source:source("Chevrolet Performance 350/290 HP long-block specifications", "https://www.chevrolet.com/content/dam/chevrolet/na/us/english/index/performance/resources/installation-guides/crate-engines/02-pdf/350-290-hp-long-block-crate-engine-19172591.pdf", "Primary Chevrolet Performance guide listing 63 lb-ft for the crankshaft-balancer bolt and 35 lb-ft for the balancer pulley on the covered engine."),diagram:"timing"},
  {slug:"ford/302/intake-manifold-torque",keyword:"ford 302 intake manifold torque specs",make:"Ford",model:"1996 F-150 5.0L/302 V8",title:"Ford 302 Intake Manifold Torque Specs and Sequence",answer:"For the covered 1996 F-150 5.0L/302, tighten the lower intake-manifold attaching bolts in Ford's illustrated sequence to 23–25 lb-ft (32–34 N·m).",scope:"This value and sequence apply to the documented 1996 truck 5.0L production intake. Earlier carbureted engines, aftermarket aluminum manifolds, different heads and gasket systems require their matching instructions.",detail:"Ford's installation figure also controls sealer placement. Replace the removed gaskets, seals and specified sealing washer rather than trying to correct a leak by exceeding 25 lb-ft.",values:[{label:"Lower intake final",value:"23–25 lb-ft",note:"32–34 N·m; exact Ford sequence"},{label:"Upper-to-lower intake",value:"12–18 lb-ft",note:"Separate fastener group in 1996 data"},{label:"Sealer placement",value:"Factory illustration",note:"Do not coat every surface indiscriminately"},{label:"Aftermarket aluminum intake",value:"Manufacturer procedure",note:"May use another value"}],source:source("1996 Ford F-150 factory service data — 5.0L intake manifold", "https://charm.li/Ford/1996/F%20150%202WD%20Pickup%20V8-302%205.0L/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Intake%20Manifold/Service%20and%20Repair/", "Factory-service-data transcription specifying 23–25 lb-ft in the illustrated sequence and application-specific sealer placement for the covered 5.0L intake."),diagram:"intake"},
  {slug:"ford/302/rocker-arm-torque",keyword:"ford 302 rocker arm torque specs",make:"Ford",model:"1996 F-150 5.0L/302 V8",title:"1996 Ford 302 Rocker Arm Torque and Preload Checks",answer:"For the covered 1996 F-150 5.0L/302 pedestal valvetrain, tighten each rocker-arm fulcrum bolt to 18–24 lb-ft (24–32 N·m). This is a production pedestal-bolt specification, not a universal setting for stud-adjustable or aftermarket roller rockers.",scope:"The range is anchored to the production 1996 truck 5.0L cylinder heads, fulcrums and bolts. Earlier rail rockers, screw-in studs, guideplates, pedestal shims, altered camshafts and aftermarket roller systems require their own geometry and adjustment instructions.",detail:"Keep each pushrod, rocker and fulcrum in its original location when reusing serviceable parts. Rotate the engine so the lifter is on the cam's base circle before tightening, then confirm acceptable hydraulic-lifter preload and free valve motion; reaching 18–24 lb-ft does not correct a mismatched pushrod or machined-head stack-up.",values:[{label:"Rocker-arm fulcrum bolt",value:"18–24 lb-ft",note:"24–32 N·m; production pedestal system"},{label:"Stud-adjustable rocker",value:"Set lash or preload",note:"Not tightened to the pedestal range"},{label:"Preload verification",value:"Required",note:"Check geometry at the cam base circle"},{label:"Aftermarket roller system",value:"Manufacturer procedure",note:"May need shims or different pushrods"}],source:source("1996 Ford F-150 5.0L factory torque specifications", "https://charm.li/Ford/1996/F%20150%202WD%20Pickup%20V8-302%205.0L/Repair%20and%20Diagnosis/Specifications/Mechanical%20Specifications/Engine/System%20Specifications/Torque%20Specifications/", "Factory-service-data transcription listing 18–24 lb-ft for the rocker-arm fulcrum bolt on the covered production 5.0L truck engine."),diagram:"valve"},
  {slug:"ford/351-windsor/intake-manifold-torque",keyword:"ford 351 windsor intake manifold torque specs",make:"Ford",model:"1993 F-150 5.8L/351W V8",title:"Ford 351 Windsor Intake Manifold Torque Specs",answer:"For the covered 1993 F-150 5.8L/351 Windsor, tighten the intake-manifold-to-head bolts in the factory sequence to 23–25 lb-ft (32–33 N·m).",scope:"The exact value is tied to the documented 1993 truck 351W production manifold. It does not cover 351 Cleveland, 351M/400, a 302 intake, or aftermarket aluminum combinations.",detail:"Dry-fit the correct-width 351W manifold, confirm port and coolant-passage alignment, and follow the gasket/sealer instructions before applying the numbered Ford sequence.",values:[{label:"Manifold-to-head final",value:"23–25 lb-ft",note:"32–33 N·m; Ford sequence"},{label:"Lower EFI intake to head",value:"22–32 lb-ft",note:"30–43 N·m in covered data"},{label:"Upper-to-lower intake",value:"12–18 lb-ft",note:"16–24 N·m; separate group"},{label:"Aftermarket aluminum",value:"Manufacturer chart",note:"Material and gasket dependent"}],source:source("1993 Ford F-150 factory service data — 5.8L intake manifold", "https://charm.li/Ford/1993/F%20150%202WD%20Pickup%20V8-351%205.8L/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Cylinder%20Head%20Assembly/Service%20and%20Repair/", "Factory-service-data transcription specifying 23–25 lb-ft in the illustrated intake-manifold sequence for the covered 5.8L Windsor."),diagram:"intake"},
  {slug:"chevrolet/ls1/head-bolt-torque-sequence",keyword:"chevy ls1 head bolt torque sequence",make:"Chevrolet",model:"2002 Camaro LS1 5.7L V8",title:"Chevy LS1 Head Bolt Torque Sequence and Stages",answer:"For the covered 2002 Camaro LS1, all M11 bolts receive 22 lb-ft and 90°. On the final pass, the standard M11 positions receive another 90°, while the medium front/rear M11 bolts receive 50°. The inner M8 bolts receive 22 lb-ft.",scope:"The chart applies to the 2002 Camaro LS1 factory-bolt design. Other LS years, post-2004 short-style bolt revisions, truck blocks and aftermarket studs require their matching procedure.",detail:"Keep medium M11 bolts identified before assembly and use an angle meter. Do not apply the 90° final turn to positions assigned 50°.",values:[{label:"All M11 initial",value:"22 lb-ft",note:"30 N·m; exact sequence"},{label:"All M11 second pass",value:"90°",note:"Angle meter required"},{label:"Standard M11 final",value:"90°",note:"Excludes medium front/rear bolts"},{label:"Medium M11 final",value:"50°",note:"Front and rear of each head"},{label:"M8 inner bolts",value:"22 lb-ft",note:"30 N·m; separate group"}],source:source("2002 Chevrolet Camaro LS1 factory service data — cylinder-head specifications", "https://charm.li/Chevrolet/2002/Camaro%20V8-5.7L%20VIN%20G/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Cylinder%20Head%20Assembly/Specifications/", "Factory-service-data transcription specifying the LS1 M11 initial/angle stages, separate 50° medium-bolt finish and 22-lb-ft M8 group."),diagram:"head"},
  {slug:"chevrolet/ls1/intake-manifold-torque",keyword:"chevy ls1 intake manifold torque specs",make:"Chevrolet",model:"2002 Camaro LS1 5.7L V8",title:"Chevy LS1 Intake Manifold Torque Specs and Sequence",answer:"For the covered 2002 Camaro LS1 composite intake, tighten the manifold bolts in sequence to 44 in-lb (5 N·m), then repeat the sequence to 89 in-lb (10 N·m).",scope:"The two-pass chart is tied to the production 2002 Camaro LS1 intake. Truck manifolds, later LS revisions and aftermarket aluminum or fabricated intakes need their own instructions.",detail:"These are inch-pound values. Inspect the reusable-style port seals and manifold flatness, keep the ports clean, and never substitute 44/89 foot-pounds.",values:[{label:"Pass 1",value:"44 in-lb",note:"5 N·m; exact sequence"},{label:"Final pass",value:"89 in-lb",note:"10 N·m; repeat sequence"},{label:"Unit",value:"Inch-pounds",note:"Not ft-lb"},{label:"Aftermarket intake",value:"Manufacturer procedure",note:"Factory composite chart may not apply"}],source:source("2002 Chevrolet Camaro LS1 factory service data — intake manifold", "https://charm.li/Chevrolet/2002/Camaro%20V8-5.7L%20VIN%20G/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Cylinder%20Head%20Assembly/Specifications/", "Factory-service-data transcription specifying 44 and 89 in-lb sequence passes for the covered LS1 composite intake."),diagram:"intake"},
  {slug:"chevrolet/454/intake-manifold-torque",keyword:"chevy 454 intake manifold torque specs",make:"Chevrolet",model:"ZZ454/440 Gen VI Big-Block V8",title:"Chevy 454 Intake Manifold Torque Specs and Sequence",answer:"For Chevrolet Performance's ZZ454/440 Gen VI crate engine, tighten the intake-manifold bolts in two complete passes: first to 10 lb-ft (14 N·m), then to 25 lb-ft (34 N·m).",scope:"The numerical chart is anchored to Chevrolet Performance ZZ454/440 part number 12498777/19433410 with its production dual-plane aluminum intake and aluminum oval-port heads. Mark IV builds, 454 HO combinations, Vortec 7.4L port-injected engines and aftermarket heads or manifolds must use their matching instructions.",detail:"The cited installation guide supplies the stages and final torque; use the numbered sequence furnished with the exact manifold or service manual. Do not transfer the 25-lb-ft carbureted crate-engine value to a Vortec 7.4L upper composite plenum.",values:[{label:"Pass 1",value:"10 lb-ft",note:"14 N·m; complete exact sequence"},{label:"Final pass",value:"25 lb-ft",note:"34 N·m; repeat sequence"},{label:"Covered engine",value:"ZZ454/440",note:"Gen VI crate engine with dual-plane intake"},{label:"Vortec 7.4L SFI",value:"Different procedure",note:"Separate lower and upper manifold fasteners"}],source:source("Chevrolet Performance ZZ454/440 installation guide", "https://www.chevrolet.com/content/dam/chevrolet/na/us/english/index/performance/resources/installation-guides/crate-engines/01-images/zz454-installation-guide-12498777.pdf", "Primary Chevrolet Performance guide specifying 10 and 25 lb-ft intake-manifold passes for the covered ZZ454/440 crate engine."),diagram:"intake"},
  {slug:"ford/4-6/head-bolt-torque-sequence",keyword:"ford 4.6 head bolt torque sequence",make:"Ford",model:"1998 Mustang GT 4.6L SOHC 2V",title:"1998 Ford 4.6 2V Head Bolt Torque Sequence",answer:"For the covered 1998 Mustang GT 4.6L SOHC 2-valve engine, install new head bolts and tighten in sequence to 28–31 lb-ft, turn 85–95°, loosen at least one full turn, retighten to 28–31 lb-ft, then complete two more 85–95° turns.",scope:"This six-stage chart applies to the documented 1998 Mustang GT 4.6L SOHC 2V. Later 3-valve engines, DOHC 4-valve engines, Romeo/Windsor production changes, remanufactured assemblies and aftermarket studs require their exact procedure.",detail:"Ford specifies new torque-to-yield bolts and oil on the bolt-head spot faces for this application. Position the crank and camshafts exactly as the installation procedure requires before placing the heads because incorrect timing position can allow valve-to-piston contact.",values:[{label:"Stage 1",value:"28–31 lb-ft",note:"37–43 N·m; numbered sequence"},{label:"Stage 2",value:"+85–95°",note:"Angle gauge required"},{label:"Stage 3",value:"Loosen 360° minimum",note:"Complete sequence"},{label:"Stage 4",value:"28–31 lb-ft",note:"Retighten in sequence"},{label:"Stages 5 and 6",value:"+85–95° each",note:"Two separate angle passes; new bolts"}],source:source("1998 Mustang GT 4.6L SOHC cylinder-head installation", "https://charm.li/Ford/1998/Mustang%20GT%20V8-4.6L%20SOHC%20VIN%20X/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Cylinder%20Head%20Assembly/Service%20and%20Repair/Installation/", "Factory-service-data transcription requiring new bolts and the covered six-stage 28–31-lb-ft/angle/loosen/retighten procedure."),diagram:"head"},
  {slug:"ford/5-4-triton/head-bolt-torque-sequence",keyword:"ford 5.4 triton head bolt torque sequence",make:"Ford",model:"2005 F-150 5.4L SOHC 3V",title:"2005 Ford 5.4 Triton 3V Head Bolt Torque Sequence",answer:"For the covered 2005 F-150 5.4L SOHC 3-valve engine, install new head bolts and tighten in the factory sequence to 30 lb-ft (40 N·m), then turn every bolt an additional 90°, followed by a second 90° turn.",scope:"This three-stage chart applies to the documented 2005 F-150 5.4L 3V VIN 5. Earlier 2-valve Triton engines, 4-valve performance engines, other model years and aftermarket studs must be matched to their separate service information.",detail:"Ford identifies these as single-use torque-to-yield bolts and prohibits sealing sprays on the dry head gasket. Clean coolant and debris from the deck and bores, locate the gasket and head on the dowels, and keep the crankshaft in the specified safe position until the timing-chain steps permit rotation.",values:[{label:"Stage 1",value:"30 lb-ft",note:"40 N·m; exact bank-specific sequence"},{label:"Stage 2",value:"+90°",note:"Angle gauge required"},{label:"Stage 3",value:"+90°",note:"Second complete angle pass"},{label:"Head bolts",value:"New only",note:"Torque-to-yield; discard removed bolts"},{label:"Head gasket",value:"Install dry",note:"No copper spray, glue or sealing aid"}],source:source("2005 Ford F-150 5.4L 3V cylinder-head installation", "https://charm.li/Ford/2005/F%20150%202WD%20Pickup%20V8-5.4L%20SOHC%20VIN%205/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Cylinder%20Head%20Assembly/Service%20and%20Repair/Installation/Part%201/", "Factory-service-data transcription requiring new bolts, a dry gasket and 30-lb-ft plus 90-degree plus 90-degree stages for the covered 5.4L 3V."),diagram:"head"},
  {slug:"chevrolet/5-3/intake-manifold-torque",keyword:"chevy 5.3 intake manifold torque specs",make:"Chevrolet",model:"2005 Silverado 5.3L VIN B V8",title:"Chevy 5.3 Intake Manifold Torque Specs by Generation",answer:"For the covered 2005 Silverado 5.3L, install new intake gaskets, apply the specified 5 mm band of threadlocker to the bolts, then tighten in sequence to 44 in-lb and finally 89 in-lb.",scope:"The procedure is anchored to the 2005 Gen III truck 5.3L VIN B composite intake. Later Gen IV/Gen V engines, active-runner systems and aftermarket manifolds require their exact service data.",detail:"The manifold, throttle body, fuel rail and injectors may be handled as an assembly in the cited procedure. Seal alignment and correct harness/PCV routing must be checked before the low final torque is applied.",values:[{label:"Pass 1",value:"44 in-lb",note:"5 N·m; exact sequence"},{label:"Final pass",value:"89 in-lb",note:"10 N·m"},{label:"Gaskets",value:"Install new",note:"Do not reuse removed intake seals"},{label:"Bolt threadlocker",value:"5 mm band",note:"Specified GM product or equivalent in covered procedure"}],source:source("2005 Chevrolet Silverado 5.3L factory service data — intake installation", "https://charm.li/Chevrolet/2005/Silverado%201500%202WD%20V8-5.3L%20VIN%20B/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Service%20and%20Repair/Overhaul/Repair%20Instructions/83.%20Intake%20Manifold%20Installation/", "Factory-service-data transcription requiring new gaskets, specified threadlocker placement and 44/89 in-lb sequence passes for the covered truck intake."),diagram:"intake"},
  {slug:"dodge/5-7-hemi/intake-manifold-torque",keyword:"dodge 5.7 hemi intake manifold torque specs",make:"Dodge",model:"2011 Ram 2500 5.7L HEMI V8",title:"Dodge 5.7 HEMI Intake Manifold Torque Specs",answer:"For the covered 2011 Ram 2500 5.7L HEMI, tighten the intake-manifold bolts in the factory sequence to 12 N·m (9 lb-ft).",scope:"This value and installation workflow are anchored to the 2011 Ram 2500 5.7L factory procedure. Passenger-car HEMIs, other model years, active-runner revisions and aftermarket manifolds require application-specific confirmation.",detail:"Install new manifold and PCV seals, connect the MAP sensor and short-runner-valve wiring as the manifold is positioned, and verify that no harness, hose or vacuum connection is trapped before tightening. The procedure calls for Mopar Lock & Seal Adhesive on the bolts when reinstalling the original manifold, but says it is not required with a new manifold.",values:[{label:"Intake-manifold bolts",value:"9 lb-ft",note:"12 N·m; factory sequence"},{label:"Manifold seals",value:"Install new",note:"Include specified PCV seals"},{label:"Original manifold bolts",value:"Lock & Seal Adhesive",note:"Per covered Mopar installation"},{label:"New manifold",value:"No bolt adhesive required",note:"Per covered procedure"}],source:source("2011 Ram 2500 5.7L factory service data — intake installation", "https://charm.li/Dodge%20and%20Ram/2011/RAM%202500%20Truck%202WD%20V8-5.7L/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Intake%20Manifold/Service%20and%20Repair/Removal%20and%20Replacement/Intake%20Manifold%20-%20Installation/", "Factory-service-data transcription specifying new seals, bolt-adhesive conditions and a 12 N·m (9 lb-ft) sequence torque for the covered 5.7L HEMI."),diagram:"intake"},
  {slug:"subaru/ej25/intake-manifold-torque",keyword:"subaru ej25 intake manifold torque specs",make:"Subaru",model:"2003 Impreza 2.5L SOHC EJ25",title:"Subaru EJ25 Intake Manifold Torque Specs by Engine Code",answer:"For the covered 2003 Subaru Impreza 2.5L SOHC EJ25, tighten the intake-manifold-to-cylinder-head bolts to 25 N·m (18.1 lb-ft) after installing new intake-manifold gaskets.",scope:"The exact value is anchored to the naturally aspirated 2003 Impreza 2.5L SOHC application. Turbo EJ255/EJ257 engines, earlier DOHC EJ25 variants, later electronic-throttle layouts and aftermarket manifolds require their own service information.",detail:"The manifold bridges two cylinder heads, so both gasket pairs must remain seated as the assembly is lowered into place. The 18.1-lb-ft figure applies to the manifold-to-head joint, not to fuel-rail, throttle-body, sensor or support-bracket fasteners.",values:[{label:"Intake manifold to heads",value:"18.1 lb-ft",note:"25 N·m; covered 2.5L SOHC"},{label:"Intake gaskets",value:"Replace with new",note:"Factory installation instruction"},{label:"Turbo EJ255/EJ257",value:"Verify separately",note:"Different manifold and plumbing"},{label:"Small attached fasteners",value:"Separate specifications",note:"Do not apply 18.1 lb-ft universally"}],source:source("2003 Subaru Impreza 2.5L SOHC factory service data — intake installation", "https://charm.li/Subaru/2003/Impreza%20F4-2.5L%20SOHC/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Intake%20Manifold/Service%20and%20Repair/Removal%20and%20Installation/", "Factory-service-data transcription directing new intake gaskets and 25 N·m (18.1 lb-ft) manifold-to-head torque for the covered naturally aspirated EJ25."),diagram:"intake"},
  {slug:"toyota/22r/head-bolt-torque",keyword:"toyota 22r head bolt torque spec",make:"Toyota",model:"1990 Toyota Pickup 22R I4",title:"Toyota 22R Head Bolt Torque Specs and Sequence",answer:"For the covered 1990 Toyota Pickup 22R, tighten the cylinder-head bolts gradually in the factory sequence through three complete passes, finishing at 58 lb-ft (78 N·m).",scope:"The numerical procedure is anchored to the 1990 2WD Pickup 22R factory service data. Other years, 22R-E revisions, replacement gaskets, aftermarket heads and stud kits must be matched to their own instructions.",detail:"The factory procedure installs the rocker-arm assembly over its dowels before tightening. Prepare the block/head joint and timing-cover interface exactly as the full model-year manual directs, then complete each pass across the entire pattern before increasing torque.",values:[{label:"Number of passes",value:"3 progressive passes",note:"Follow the exact Toyota sequence"},{label:"Final pass",value:"58 lb-ft",note:"78 N·m; 800 kgf·cm"},{label:"Thread and gasket preparation",value:"Model-year procedure",note:"Do not improvise lubricant or sealer"},{label:"Aftermarket studs or head",value:"Component-maker chart",note:"Factory bolt torque does not transfer"}],source:source("1990 Toyota Pickup factory service data — 22R cylinder head", "https://charm.li/Toyota/1990/Pickup%202WD%20L4-2366cc%202.4L%20SOHC%20%2822R%29/Repair%20and%20Diagnosis/Specifications/Mechanical%20Specifications/Engine/System%20Specifications/Torque%20Specifications/Cylinder%20Head/", "Factory-service-data transcription directing three gradual sequence passes and a 58 lb-ft (78 N·m) final torque for the covered 1990 22R."),diagram:"head"},
  {slug:"jeep/4-0/head-bolt-torque",keyword:"jeep 4.0 head bolt torque spec",make:"Jeep",model:"2001 Cherokee 4.0L Inline-Six",title:"Jeep 4.0 Head Bolt Torque Specs and Sequence",answer:"For the 2001 Jeep Cherokee 4.0L, tighten all 14 head bolts to 22 lb-ft and then 45 lb-ft in sequence; finish bolts 1–10 and 12–14 at 110 lb-ft, while bolt 11 finishes at 100 lb-ft.",scope:"These stages apply to the documented 2001 Cherokee 4.0L VIN S factory-bolt procedure. Other years, remanufactured engines, replacement castings, gaskets and aftermarket studs require their exact documentation.",detail:"Bolt 11 is deliberately lower than the others and must not be overtightened. The manual also requires a 45-lb-ft verification pass, a final sequence check, and replacement of bolts already carrying a paint mark from an earlier service operation.",values:[{label:"Pass 1 — all 14 bolts",value:"22 lb-ft",note:"30 N·m; exact sequence"},{label:"Pass 2 — all 14 bolts",value:"45 lb-ft",note:"61 N·m; then verify all at 45"},{label:"Final — bolts 1–10 and 12–14",value:"110 lb-ft",note:"149 N·m"},{label:"Final — bolt 11 only",value:"100 lb-ft",note:"135 N·m; do not overtighten"},{label:"Previously paint-marked bolts",value:"Replace",note:"Per covered factory procedure"}],source:source("2001 Jeep Cherokee factory service data — 4.0L cylinder head", "https://charm.li/Jeep/2001/Cherokee%202WD%20LHD%20L6-4.0L%20VIN%20S/Repair%20and%20Diagnosis/Specifications/Mechanical%20Specifications/Engine/System%20Specifications/Engine%20Torque%20Specifications/Cylinder%20Head/", "Factory-service-data transcription giving the 22/45/110-lb-ft stages, the separate 100-lb-ft final value for bolt 11, and the bolt-marking/replacement rule."),diagram:"head"},
  {slug:"ford/300-inline-6/head-bolt-torque",keyword:"ford 300 inline 6 head bolt torque spec",make:"Ford",model:"1993 F-150 4.9L/300 Inline-Six",title:"Ford 300 Inline-6 Head Bolt Torque Specs and Sequence",answer:"For the covered 1993 Ford F-150 4.9L/300 inline-six, tighten the cylinder-head bolts in the illustrated sequence through 50–55 lb-ft, 60–65 lb-ft, and a final 70–85 lb-ft pass.",scope:"The three-stage chart is anchored to the 1993 F-150 4.9L factory service procedure. Earlier 240/300 versions, later revisions, replacement heads, gasket-specific instructions and stud kits must be checked separately.",detail:"The long cast-iron head magnifies the importance of flatness, clean bolt holes and full-pattern staged tightening. Complete every bolt in the Ford sequence before moving to the next range; do not select 85 lb-ft and apply it one bolt at a time.",values:[{label:"Pass 1",value:"50–55 lb-ft",note:"68–75 N·m; exact Ford sequence"},{label:"Pass 2",value:"60–65 lb-ft",note:"81–88 N·m; repeat full pattern"},{label:"Final pass",value:"70–85 lb-ft",note:"95–115 N·m; covered 1993 application"},{label:"Aftermarket studs/head",value:"Component-maker procedure",note:"Specified lubricant controls clamp load"}],source:source("1993 Ford F-150 factory service data — 4.9L cylinder head", "https://charm.li/Ford/1993/F%20150%202WD%20Pickup%20L6-300%204.9L/Repair%20and%20Diagnosis/Engine%2C%20Cooling%20and%20Exhaust/Engine/Cylinder%20Head%20Assembly/Service%20and%20Repair/", "Factory-service-data transcription specifying 50–55, 60–65 and 70–85 lb-ft sequence passes for the covered F-150 L6-300/4.9L."),diagram:"head"},
];

const researchedTorqueEditorial:Record<string,{sections:SpecRecord["sections"];faqs:SpecRecord["faqs"]}>={
  "chevrolet/350/rocker-arm-torque":{sections:[{heading:"Preload is an adjustment, not a universal nut torque",paragraphs:["With the lifter resting on the cam base circle, remove clearance until the pushrod just stops rotating freely: that is zero lash. Chevrolet then calls for another one-half to one full turn of the adjusting nut to place the hydraulic lifter in its working range.","The 15–20-lb-ft number belongs only to the internal poly-lock set screw while the outer nut is held. Applying it as a final torque to an ordinary stamped-rocker nut would confuse two different valvetrain designs."]},{heading:"Clearance checks protect the complete valvetrain",paragraphs:["Rotate the engine through the entire lift cycle and verify the published minimums at the retainer, rocker slot and pushrod hole. Check valve-cover baffles as well; contact at any of these points can damage a rocker or falsely limit valve motion.","A solid-lifter cam uses the cam card's hot or cold lash, not hydraulic preload. Stud girdles and other roller-rocker systems also follow their own locking sequence and geometry requirements."]}],faqs:[{q:"What is the Chevy 350 hydraulic rocker adjustment?",a:"For the covered Chevrolet Performance roller system, set zero lash and add one-half to one full turn of preload."},{q:"What torque applies to the poly-lock set screw?",a:"Hold the outer nut and tighten the internal set screw to 15–20 lb-ft, then lock both together no more than another quarter turn."},{q:"Does a solid-lifter Chevy 350 use zero lash plus preload?",a:"No. Set the intake and exhaust lash specified by the exact camshaft card."},{q:"What rocker-to-retainer clearance is required?",a:"The covered instructions require at least 0.040 inch throughout the full rocker travel."}]},
  "chevrolet/350/flywheel-bolt-torque":{sections:[{heading:"What the 65–70-lb-ft range covers",paragraphs:["The value clamps the manual flywheel directly to the crankshaft on the Chevrolet Performance 350/290 package. Pressure-plate bolts, bellhousing bolts and an automatic flexplate are separate joints and should appear on different rows of the repair worksheet.","Inspect the threaded holes and use the specified production or approved replacement bolts. A performance fastener's lubricant can change friction enough that its manufacturer's torque replaces the factory figure."]},{heading:"Balance and runout matter as much as torque",paragraphs:["Match flywheel imbalance and rear-main-seal architecture to the crankshaft before assembly. Clean mating faces, remove burrs and draw the flywheel down in progressive crossing passes so contamination cannot hold it crooked.","Check ring-gear condition and runout when the component instructions require it. Extra torque cannot correct the wrong imbalance, an incorrect pilot bearing or a flywheel that is not seated flat."]}],faqs:[{q:"What is the Chevrolet Performance 350 flywheel torque?",a:"The covered 350/290 HP package specifies 65–70 lb-ft (88–95 N·m)."},{q:"Does that range apply to pressure-plate bolts?",a:"No. Pressure-plate-to-flywheel fasteners use a separate clutch specification."},{q:"Can a one-piece-seal flywheel fit every Chevy 350 crank?",a:"No. Rear-main-seal design, bolt pattern and imbalance must match the crankshaft."},{q:"Do aftermarket flywheel bolts use 65–70 lb-ft?",a:"Follow the bolt maker's torque and specified lubricant for that exact kit."}]},
  "chevrolet/350/flexplate-bolt-torque":{sections:[{heading:"Keep the crank and converter fasteners separate",paragraphs:["The 1988 truck chart uses 75 lb-ft where the flexplate clamps to the crankshaft and 50 lb-ft where the torque converter attaches to the plate. Swapping the values can overload the converter lugs or under-clamp the crank joint.","Rotate the engine by the approved method to access each converter fastener and confirm the converter remains seated correctly in the transmission pump before the transmission is pulled to the engine."]},{heading:"Orientation and balance checks before torque",paragraphs:["Verify the flexplate's offset, balance weight, ring-gear tooth count and converter pattern. Mark the installed direction during removal when appropriate; a plate mounted backward can create starter and converter alignment problems even when all bolts are tight.","Clean the crank flange and flexplate, start every correct-length bolt by hand and tighten evenly. A replacement flexplate or fastener kit may specify a threadlocker or torque different from the production hardware."]}],faqs:[{q:"What is the 1988 Chevy 350 flexplate-to-crank torque?",a:"The covered C1500 specification is 75 lb-ft (100 N·m)."},{q:"What is the flexplate-to-converter torque?",a:"The separate converter fasteners use 50 lb-ft (65 N·m)."},{q:"Can the flexplate be installed either direction?",a:"No. Its offset, balance weight and converter relationship require the correct application-specific orientation."},{q:"Is flexplate balance the same on every Chevy 350?",a:"No. Crankshaft and rear-main-seal generations must be matched to the correct neutral or externally balanced plate."}]},
  "chevrolet/350/harmonic-balancer-bolt-torque":{sections:[{heading:"Retaining bolt versus pulley bolts",paragraphs:["Chevrolet Performance lists 63 lb-ft for the center balancer retaining bolt and 35 lb-ft for the bolts attaching the pulley to the balancer. They differ in size and purpose; do not apply the center-bolt setting around the pulley flange.","Confirm the washer and key are correct and inspect the elastomer for separation. A visibly shifted inertia ring requires damper replacement, not a tighter center bolt."]},{heading:"Use the installer before final torque",paragraphs:["Thread the proper installer deeply into the crankshaft and press on the hub, never the outer inertia ring. Align the keyway and stop if force rises unexpectedly so burrs, a displaced key or the wrong bore can be corrected.","The final retaining bolt supplies clamp after seating; using it to drag the damper the entire distance risks stripping the first crank threads. Aftermarket dampers and reusable performance bolts follow their matched lubricant and torque instructions."]}],faqs:[{q:"What is the Chevrolet Performance 350 balancer-bolt torque?",a:"The covered 350/290 HP package specifies 63 lb-ft (85 N·m)."},{q:"What is the balancer-pulley bolt torque?",a:"The separate pulley fasteners use 35 lb-ft (47 N·m)."},{q:"Can the center bolt install the damper?",a:"No. Seat the hub with a dedicated balancer installer before tightening the retaining bolt."},{q:"Does every production Chevy 350 use 63 lb-ft?",a:"No. This page is anchored to the Chevrolet Performance 350/290 package; other engines require their own chart."}]},
  "ford/302/intake-manifold-torque":{sections:[{heading:"What the 1996 Ford procedure covers",paragraphs:["The 23–25-lb-ft value belongs to the lower intake attaching bolts and the illustrated 1996 truck sequence. Upper-to-lower intake bolts are a separate group at 12–18 lb-ft; combining the two groups creates an incorrect chart.","Ford also illustrates where sealer belongs. Replace disturbed gaskets, end seals and the specified sealing washer, then seat the manifold without sliding it across the ports."]},{heading:"Preventing an intake leak",paragraphs:["Dry-fit the assembly, verify dowel and coolant-passage alignment, and start every bolt by hand. Tighten progressively through the Ford order rather than taking one corner directly to 25 lb-ft.","Aftermarket aluminum manifolds and gasket systems may prescribe different sealant and torque. Their instructions replace—not supplement—the production cast-manifold value."]}],faqs:[{q:"What is the 1996 Ford 302 lower-intake torque?",a:"Tighten the attaching bolts in the Ford sequence to 23–25 lb-ft."},{q:"Do the upper-to-lower intake bolts also use 23–25 lb-ft?",a:"No. The covered specifications list that separate group at 12–18 lb-ft."},{q:"Can extra torque stop a Ford 302 intake leak?",a:"No. Diagnose gasket alignment, flatness, sealing surfaces and sealer placement instead of exceeding the specification."},{q:"Does an aluminum aftermarket intake use this value?",a:"Only if its manufacturer explicitly says so; follow the manifold and gasket instructions."}]},
  "ford/351-windsor/intake-manifold-torque":{sections:[{heading:"The 1993 truck 351W application",paragraphs:["Ford specifies 23–25 lb-ft for the manifold-to-head fasteners in its numbered pattern. EFI upper/lower fasteners are separate groups, so identify exactly which joint is being assembled before setting the wrench.","A 351W intake is wider than a 289/302 intake because of the taller deck. Correct torque cannot seal a mismatched manifold or compensate for port and coolant-passage misalignment."]},{heading:"Assembly details that control sealing",paragraphs:["Dry-fit first, then apply the gasket maker's approved sealer only at the required coolant and end-rail locations. Lower the intake squarely so the seals do not shift.","Use gradual passes through the factory sequence. If aluminum heads, an aftermarket intake or a nonstandard gasket is present, use the matched component instructions and surface-finish requirements."]}],faqs:[{q:"What is the 1993 Ford 351W intake-manifold torque?",a:"The covered F-150 procedure specifies 23–25 lb-ft in the factory sequence."},{q:"Will a Ford 302 intake fit a 351W?",a:"Not as a direct production replacement; the 351W's taller deck creates a wider intake span."},{q:"Are upper and lower EFI intake bolts the same torque?",a:"No. The covered service data lists separate fastener groups and values."},{q:"Should an aluminum 351W intake use 25 lb-ft?",a:"Use the intake and gasket manufacturers' instructions; they may specify another value or sequence."}]},
  "chevrolet/ls1/intake-manifold-torque":{sections:[{heading:"Why 44 and 89 are inch-pounds",paragraphs:["The LS1 composite manifold needs only 5 N·m on the first pass and 10 N·m on the final pass. In imperial units those are 44 and 89 inch-pounds—not foot-pounds. A foot-pound mistake can crush the composite bosses or pull threads.","Use a calibrated inch-pound wrench near the middle of its working range and complete the exact sequence at 44 before repeating it at 89."]},{heading:"Seal and flatness checks",paragraphs:["Inspect every port seal, the manifold deck and the cylinder-head sealing surfaces. Keep debris out of the runners and confirm the manifold settles without harnesses or hoses trapped underneath.","Do not add sealant unless the exact procedure or replacement-manifold maker directs it. A pinched O-ring remains a leak even if the bolts are overtightened."]}],faqs:[{q:"What is the 2002 Camaro LS1 intake torque?",a:"Use 44 in-lb for the first sequence pass and 89 in-lb for the final pass."},{q:"Are those LS1 values foot-pounds?",a:"No. They are inch-pounds: 5 N·m and 10 N·m."},{q:"Can the intake bolts be tightened harder to stop a vacuum leak?",a:"No. Inspect seals, flatness and seating; overtightening can damage the composite manifold."},{q:"Does this chart cover an aftermarket aluminum LS intake?",a:"No assumption is safe. Follow the manifold manufacturer's fastener and gasket procedure."}]},
  "chevrolet/5-3/intake-manifold-torque":{sections:[{heading:"The complete 2005 truck intake preparation",paragraphs:["The factory procedure calls for new manifold-to-head gaskets and a 5 mm band of the specified threadlocker on the intake bolts. With the manifold seated and every bolt started, tighten the numbered sequence to 44 in-lb and then 89 in-lb.","The low torque is intentional for the composite manifold. Check that injector, MAP, PCV, EVAP and harness routing is correct before the final pass because trapped components can prevent full seating."]},{heading:"Generation and manifold boundaries",paragraphs:["This page is anchored to a 2005 Gen III truck 5.3L. Later active-runner manifolds, direct-injected Gen V EcoTec3 engines and aftermarket intakes can change fasteners, seals and procedures even when the displacement badge still says 5.3.","If a vacuum leak remains, smoke-test and inspect the seals rather than adding torque. Warpage, a rolled gasket or a cracked port cannot be repaired by crushing the manifold harder."]}],faqs:[{q:"What is the 2005 Silverado 5.3 intake torque?",a:"Tighten in sequence to 44 in-lb, then repeat the sequence to 89 in-lb."},{q:"Can the removed 5.3 intake gaskets be reused?",a:"No. The covered factory installation procedure directs installation of new manifold-to-head gaskets."},{q:"Does the covered procedure use threadlocker?",a:"Yes. It specifies a 5 mm band of the named GM threadlocker or equivalent on the intake bolts."},{q:"Does this chart cover Gen V EcoTec3 5.3L engines?",a:"No. Later generations require their exact RPO and service procedure."}]},
  "chevrolet/454/intake-manifold-torque":{sections:[{heading:"The ZZ454/440 two-pass specification",paragraphs:["Chevrolet Performance publishes 10 lb-ft (14 N·m) for the first complete pass and 25 lb-ft (34 N·m) for the second. Bringing the complete pattern up in stages lets the dual-plane aluminum manifold settle across both banks before final clamp load is applied.","Use the exact numbered pattern supplied with the manifold or engine instructions. Start every bolt by hand, keep the intake square over the ports and complete the entire first pass before increasing the wrench setting."]},{heading:"Why another 454 chart may be different",paragraphs:["The 454 name spans Mark IV, Gen V and Gen VI big-blocks plus carbureted and Vortec 7.4L fuel-injected applications. For example, the later Vortec arrangement has separate lower-manifold and upper-plenum fasteners; its upper composite assembly must not receive this 25-lb-ft value.","Cylinder-head material, port shape, gasket construction, bolt length and aftermarket manifold design also change the governing instructions. Identify the block generation, head casting and intake part number before treating a torque chart as applicable."]},{heading:"Sealing checks before final torque",paragraphs:["Dry-fit the manifold and confirm port, coolant-passage and distributor clearance before adding sealant. Follow the gasket maker's directions at the end rails and water ports; more sealant is not a substitute for correct bead placement or flat surfaces.","If the manifold rocks, a bolt binds or a gap remains at one bank, stop. Final torque cannot correct a mismatched port face, trapped gasket, incorrect bolt or distorted intake."]}],faqs:[{q:"What is the Chevrolet Performance ZZ454 intake-manifold torque?",a:"Use 10 lb-ft (14 N·m) for the first complete pass and 25 lb-ft (34 N·m) for the final pass."},{q:"Does 25 lb-ft apply to a Vortec 7.4L upper intake?",a:"No. The fuel-injected Vortec 7.4L uses separate lower and upper manifold procedures, and its upper fasteners use a much lower value."},{q:"Can I use this chart with an aftermarket 454 intake?",a:"Only when the manifold and gasket manufacturers confirm the same stages, thread condition and hardware."},{q:"Should the 454 intake bolts be retorqued after a heat cycle?",a:"Only when the exact manifold or gasket instructions call for it; do not loosen a completed joint to invent a retorque procedure."}]},
  "dodge/5-7-hemi/intake-manifold-torque":{sections:[{heading:"The covered 2011 Ram 5.7L procedure",paragraphs:["Mopar's installation procedure finishes the intake-manifold bolts at 12 N·m (9 lb-ft) in its illustrated sequence. That low value is intentional for the composite manifold and molded seals; interpreting it as 9 N·m or converting it into an improvised inch-pound target changes the specification.","The procedure distinguishes a reused original manifold from a new replacement. Apply Mopar Lock & Seal Adhesive to the intake bolts with the original manifold; the factory text says the adhesive is not required when installing a new manifold."]},{heading:"Positioning the manifold without trapping components",paragraphs:["Fit new intake-manifold seals and the specified PCV seals. As the assembly is lowered, connect and route the MAP sensor and short-runner-valve wiring correctly, then verify injector connectors, vacuum hoses and harness branches are clear of every sealing rail.","Start all bolts by hand and make controlled preliminary passes through the factory order before the final 9-lb-ft pass. Do not use extra torque to pull a high corner down; remove the manifold and find the displaced seal or trapped component."]},{heading:"Application limits across HEMI generations",paragraphs:["This page is anchored to a 2011 Ram 2500 5.7L. Car and SUV applications, later active-runner systems and replacement aluminum manifolds may change the hardware, chemical treatment or sequence even though the engine badge remains 5.7 HEMI.","A persistent lean code or vacuum leak after installation calls for routing inspection and a controlled smoke test. Overtightening risks cracked bosses, distorted sealing rails and pulled threads without repairing the original leak path."]}],faqs:[{q:"What is the 2011 Ram 5.7 HEMI intake-manifold torque?",a:"Tighten the intake-manifold bolts in the factory sequence to 12 N·m (9 lb-ft)."},{q:"Are new intake-manifold seals required?",a:"Yes. The covered Mopar installation procedure directs new manifold seals and the specified PCV seals."},{q:"Do the 5.7 HEMI intake bolts need threadlocker?",a:"The covered procedure calls for Mopar Lock & Seal Adhesive when reinstalling the original manifold, but says it is not required with a new manifold."},{q:"Can 9 lb-ft be used for every 5.7 HEMI intake?",a:"No. Confirm the model year, vehicle, manifold revision and replacement-part instructions before applying the value."}]},
  "subaru/ej25/intake-manifold-torque":{sections:[{heading:"The 2003 naturally aspirated EJ25 specification",paragraphs:["Subaru specifies 25 N·m (18.1 lb-ft) for the intake manifold to the cylinder heads on the covered 2003 Impreza 2.5L SOHC. The same factory installation section directs replacement of the removed intake gaskets with new parts.","Use a calibrated wrench and bring both sides down evenly. Because the manifold spans the boxer engine's separated cylinder heads, an uneven approach can shift a gasket before the opposite bank begins to seat."]},{heading:"Keep attached-component torques separate",paragraphs:["The 18.1-lb-ft value belongs to the manifold-to-head fasteners. Fuel rails, throttle body, support brackets, sensors and small vacuum hardware each have their own fastener size and specification; applying the manifold value to them can strip threads or crack a housing.","Before the final pass, verify injector O-rings, PCV and brake-booster hoses, grounds and harness clips are correctly installed and cannot be pinched under a runner or bracket."]},{heading:"EJ25 is an engine family, not one intake",paragraphs:["The EJ25 designation includes early DOHC engines, later naturally aspirated SOHC variants and turbocharged EJ255/EJ257 applications. Turbo plumbing, tumble-generator components, electronic throttle revisions and model-year changes prevent one manifold chart from covering the whole family.","Use the engine code, VIN, model year and intake casting to select service information. If an aftermarket manifold, thermal spacer or nonstandard gasket is installed, its maker's torque and sealing directions control."]}],faqs:[{q:"What is the 2003 Subaru Impreza EJ25 intake-manifold torque?",a:"For the covered naturally aspirated 2.5L SOHC, tighten the manifold-to-head bolts to 25 N·m (18.1 lb-ft)."},{q:"Can the EJ25 intake gaskets be reused?",a:"The cited Subaru installation procedure directs replacement with new intake-manifold gaskets."},{q:"Does 18.1 lb-ft apply to fuel-rail and throttle-body bolts?",a:"No. It applies only to the intake-manifold-to-cylinder-head fasteners in the covered application."},{q:"Does this value cover EJ255 and EJ257 turbo engines?",a:"No. Turbo variants require their exact model-year manifold and service procedure."}]},
  "ford/302/head-bolt-torque-sequence":{sections:[{heading:"Identify the bolt head before choosing a chart",paragraphs:["Ford's bulletin distinguishes a non-flanged standard hex bolt from a flanged torque-to-yield bolt. A cylinder head must contain one style only; mixing them creates incompatible clamp procedures on the same casting.","Standard bolts finish by measured torque. Flanged TTY bolts finish by angle and must be replaced after use. Sort the complete set before the head is lowered onto the block, not halfway through tightening."]},{heading:"Applying the correct Ford sequence",paragraphs:["For standard bolts, complete 55–65 lb-ft across the full pattern, then 65–72 lb-ft. For flanged TTY bolts, complete 25–35 lb-ft, then 45–55 lb-ft, then measure an additional 85–95° turn.","Ford says no extended-operation retorque is required after the applicable procedure. Aluminum heads, studs or a non-stock gasket move the job to the component maker's instructions."]}],faqs:[{q:"What are the 1996 Ford 302 standard head-bolt stages?",a:"Non-flanged standard bolts use 55–65 lb-ft followed by 65–72 lb-ft in sequence."},{q:"What are the Ford 302 flanged TTY stages?",a:"Use 25–35 lb-ft, 45–55 lb-ft, then an additional 85–95° with new flanged bolts."},{q:"Can standard and TTY bolts be mixed on one 302 head?",a:"No. Ford explicitly requires one uniform bolt style on each cylinder head."},{q:"Can Ford 5.0L TTY head bolts be reused?",a:"No. The cited Ford bulletin identifies them as single-use fasteners."}]},
  "ford/351-windsor/head-bolt-torque-sequence":{sections:[{heading:"The covered 1993 351W three-pass procedure",paragraphs:["Run the complete Ford pattern at 85 lb-ft, repeat it at 95 lb-ft, and finish every position at 105–112 lb-ft. Progressive passes distribute load across the long Windsor head before the final range is reached.","Do not borrow the 5.0L/302 chart. Although both are Windsor-family engines, Ford publishes materially different head-bolt values for the 5.8L truck application."]},{heading:"Keep other 351 families out of the chart",paragraphs:["A 351 Cleveland and 351M/400 use different architecture; displacement alone is not identification. Verify block and head casting, model year and bolt set before assembly.","Aftermarket aluminum heads and studs use their manufacturers' lubricant, washer and torque procedure. A factory wrench value cannot be separated from its specified friction condition."]}],faqs:[{q:"What are the 1993 Ford 351W head-bolt stages?",a:"The covered F-150 5.8L procedure uses 85 lb-ft, 95 lb-ft, then 105–112 lb-ft in sequence."},{q:"Can I use Ford 302 head-bolt torque on a 351W?",a:"No. The cited Ford data publishes a separate, higher three-pass chart for the 5.8L Windsor."},{q:"Does this chart cover a 351 Cleveland?",a:"No. The 351C is a different engine family and needs its own procedure."},{q:"Do aluminum heads or studs use 105–112 lb-ft?",a:"Not automatically. Follow the exact head and fastener manufacturers' instructions."}]},
  "ford/302/rocker-arm-torque":{sections:[{heading:"A pedestal bolt is not a lash-adjusting nut",paragraphs:["The covered 1996 truck uses a fulcrum bolt that clamps a pedestal-style rocker assembly at 18–24 lb-ft. Traditional stud-mounted rockers are adjusted at zero lash or to a cam-card clearance instead; applying 24 lb-ft to an adjustable nut can hold a valve open.","Identify the head, rocker fulcrum and fastener before choosing a method. A rail rocker, pedestal conversion or guideplate-and-stud assembly changes both the adjustment and the geometry checks."]},{heading:"Verify preload rather than trusting torque alone",paragraphs:["Place the lifter on the cam lobe's base circle, seat the pushrod and rocker correctly and tighten with clean, compatible hardware. Then check hydraulic-lifter preload and rotate the engine by hand to verify that no valve binds.","A milled head, thinner gasket, different cam base circle or changed valve length can move preload outside its working range even while the wrench reading is correct. Correct the stack-up with the approved pushrod or shim solution instead of overtightening the fulcrum bolt."]}],faqs:[{q:"What is the 1996 Ford 302 rocker-arm bolt torque?",a:"The production rocker-arm fulcrum bolts use 18–24 lb-ft (24–32 N·m)."},{q:"Do stud-mounted Ford 302 rockers use 18–24 lb-ft?",a:"No. Adjustable stud rockers are set by hydraulic preload or specified valve lash rather than this pedestal-bolt range."},{q:"Why must preload be checked after tightening?",a:"Machining and changed valvetrain parts can alter the stack height even when the bolt reaches the factory torque."},{q:"Do aftermarket roller rockers use the factory value?",a:"Only if their manufacturer explicitly retains the production pedestal hardware and specification; otherwise follow the kit procedure."}]},
  "ford/4-6/head-bolt-torque-sequence":{sections:[{heading:"Do not omit the deliberate loosen-and-retighten stage",paragraphs:["The covered 1998 4.6L 2V procedure first reaches 28–31 lb-ft and 85–95°, then loosens the bolts at least 360 degrees. It returns to 28–31 lb-ft before two more 85–95° passes. That reset is part of Ford's clamp-load process, not an optional correction.","Complete each stage across the bank in the numbered illustration. Estimating angle by wrench position or finishing one bolt through all six stages before its neighbors defeats the specified sequence."]},{heading:"New bolts and safe engine positioning",paragraphs:["Ford identifies the head bolts as torque-to-yield and requires new fasteners. Apply oil only where the covered procedure specifies it and keep bolt holes free of coolant or debris that could hydraulically damage the block.","Position the crankshaft and camshafts as directed before installing the heads. The 4.6L is an interference engine; a correct torque chart cannot protect valves if the rotating assembly is placed in an unsafe position during timing work."]}],faqs:[{q:"What are the 1998 Ford 4.6 2V head-bolt stages?",a:"Use 28–31 lb-ft, 85–95°, loosen at least 360°, retighten to 28–31 lb-ft, then add 85–95° twice."},{q:"Can 4.6L torque-to-yield head bolts be reused?",a:"No. The covered Ford procedure requires new cylinder-head bolts."},{q:"Can this six-stage chart be used on a 4.6L 3V or 4V?",a:"No. It is anchored to the 1998 Mustang GT SOHC 2-valve application."},{q:"Can the angle turns be estimated visually?",a:"Use a proper angle gauge so each numbered fastener receives both measured turns accurately."}]},
  "ford/5-4-triton/head-bolt-torque-sequence":{sections:[{heading:"The 2005 5.4L 3V three-stage method",paragraphs:["The covered F-150 procedure is concise but demanding: 30 lb-ft, then 90 degrees, then another 90 degrees through the bank-specific pattern. Both angle turns are complete passes; they are not a single 180-degree sweep performed bolt by bolt.","Use an angle gauge and mark each bolt after a completed stage. The left and right bank illustrations differ in orientation, so follow the actual service diagram rather than mentally mirroring a generic online picture."]},{heading:"Gasket and fastener preparation",paragraphs:["Discard the removed torque-to-yield bolts and install new ones. Ford directs that the head gasket be installed dry and specifically prohibits copper spray, aviation cement and glue on this joint.","Remove coolant and foreign material without gouging the deck, check the locating dowels and hold the crankshaft in the prescribed position. Later timing-chain installation is inseparable from safe cylinder-head work on the three-valve engine."]}],faqs:[{q:"What are the 2005 Ford 5.4 3V head-bolt stages?",a:"Tighten new bolts in sequence to 30 lb-ft, then add 90 degrees, followed by another 90 degrees."},{q:"Can 5.4 Triton head bolts be reused?",a:"Not in the covered 2005 3V procedure; Ford identifies them as single-use torque-to-yield bolts."},{q:"Should copper spray be applied to the 5.4L head gasket?",a:"No. Ford directs dry installation and prohibits sealing aids on the covered gasket."},{q:"Does this chart cover the older 5.4L 2V?",a:"No. The earlier two-valve engine requires its corresponding model-year procedure."}]},
  "chevrolet/5-3/head-bolt-torque-sequence":{sections:[{heading:"Exact 2005 Gen III 5.3L bolt groups",paragraphs:["Install new M11 bolts 1–10 and take them through 22 lb-ft, 90°, and 70° in the numbered sequence. The five smaller M8 bolts are a separate group: start at the center and work outward to 22 lb-ft.","The 70° final pass identifies the covered second-design procedure. Earlier first-design blocks can use long and medium M11 bolts with position-specific 90° and 50° final turns, so bolt-hole depth and engine design cannot be guessed."]},{heading:"Preparation for torque-plus-angle fasteners",paragraphs:["Clean debris and liquid from the bolt holes, verify locating dowels and gasket direction, and install the correct new bolts without adding unapproved lubricant. Use a calibrated angle meter rather than estimating wrench-handle travel.","Gen IV and Gen V 5.3L engines are separate service applications. The 5.3 badge establishes displacement, not head-bolt design."]}],faqs:[{q:"What are the 2005 Silverado 5.3 head-bolt stages?",a:"M11 bolts 1–10 use 22 lb-ft, 90°, then 70°. M8 bolts 11–15 use 22 lb-ft in their separate center-out order."},{q:"Can the covered 5.3L head bolts be reused?",a:"No. The factory procedure directs installation of new cylinder-head bolts."},{q:"Why do some 5.3L charts show a 50° final turn?",a:"First-design engines use different long and medium bolt groups. The covered second-design 2005 procedure uses 70° for all ten M11 bolts."},{q:"Does this procedure cover Gen V EcoTec3 engines?",a:"No. Later engine generations require their exact RPO and service procedure."}]},
  "chevrolet/ls1/head-bolt-torque-sequence":{sections:[{heading:"The LS1 medium-bolt exception",paragraphs:["All M11 bolts first receive 22 lb-ft and then 90°. On the final pass, most M11 bolts turn another 90°, but the medium-length bolts at the front and rear of each head turn only 50°.","The inner M8 fasteners form a separate group and finish at 22 lb-ft. Keep bolt lengths organized during teardown so a medium bolt cannot silently receive the wrong final angle."]},{heading:"LS-family is not one universal chart",paragraphs:["This procedure is tied to the 2002 Camaro LS1. Chevrolet later introduced a short-style head-bolt design, and truck LS-family engines can use different length groups or final turns.","Use new factory bolts where required, clean the blind holes and measure each angle. Aftermarket studs replace the torque-to-yield chart with the stud maker's torque and lubricant specification."]}],faqs:[{q:"What are the 2002 Camaro LS1 head-bolt stages?",a:"All M11 bolts receive 22 lb-ft and 90°; standard positions then receive another 90°, while medium front/rear positions receive 50°. M8 bolts use 22 lb-ft."},{q:"Why do some LS1 bolts receive only 50° on the final pass?",a:"The medium-length M11 bolts at the front and rear of each head have a separate final-angle specification."},{q:"Can this LS1 chart be used on every LS engine?",a:"No. Bolt length and design changed across LS-family years and applications."},{q:"Do LS1 aftermarket studs use the factory angle stages?",a:"No. Use the stud manufacturer's torque, lubricant and sequence."}]},
  "toyota/22r/head-bolt-torque":{sections:[
    {heading:"What the 1990 Toyota procedure actually says",paragraphs:["The covered Toyota procedure does not use a torque-plus-angle finish. It calls for gradual tightening in three passes through the illustrated order, with the final pass reaching 58 lb-ft (78 N·m). Treat that as an application-specific procedure, not a universal number for every 22R-family build.","The rocker-arm assembly is positioned over its locating dowels before the head bolts are tightened. That detail affects access and stack-up, so the complete assembly sequence matters as much as the final wrench setting." ]},
    {heading:"Preparation before the first pass",paragraphs:["Confirm the block, head, gasket and bolt set belong together. Clean the mating surfaces without gouging them, chase contamination from bolt holes by the approved method, and verify that the timing-chain components and cover-to-block joint are assembled as the model-year manual requires.","Start every bolt by hand. A bolt that binds early, reaches torque before the joint seats, or shows damaged threads is a stop signal. Torque cannot compensate for trapped debris, liquid in a blind hole, incorrect bolt length or a displaced head gasket." ]},
    {heading:"How to apply three progressive passes",paragraphs:["Use a calibrated wrench and follow Toyota's numbered illustration for every pass. A sensible workflow is to divide the rise toward 58 lb-ft into two lower, even seating passes and the published final pass without exceeding the final value. The exact sequence—not an invented row-by-row sweep—controls.","After assembly, rotate the engine by hand through its normal direction and complete valve adjustment, timing and cooling-system work using the exact vehicle procedure. Apply any post-heat-cycle recheck only when the gasket or service instructions explicitly require it." ]},
  ],faqs:[{q:"What is the 1990 Toyota 22R head-bolt torque?",a:"The covered factory procedure uses three gradual sequence passes and a final torque of 58 lb-ft (78 N·m)."},{q:"Does the 1990 22R procedure use an angle turn?",a:"No angle stage appears in the cited procedure; it finishes at a measured 58 lb-ft after three progressive passes."},{q:"Can I apply 58 lb-ft to aftermarket studs?",a:"Not automatically. Use the stud maker's torque, lubricant and sequence for that exact kit."},{q:"Should the head be retorqued after running?",a:"Only when the exact gasket or model-year service instructions require it; do not invent a recheck by loosening completed bolts."}]},
  "jeep/4-0/head-bolt-torque":{sections:[
    {heading:"The complete 2001 Jeep 4.0 tightening stages",paragraphs:["Run all 14 positions through 22 lb-ft, then 45 lb-ft in the factory sequence. Verify every bolt is still at 45 lb-ft before the final pass. Bolts 1–10 and 12–14 then finish at 110 lb-ft; bolt 11 alone finishes at 100 lb-ft.","The lower value for bolt 11 is deliberate. Applying 110 lb-ft to it because most of the row uses that figure directly contradicts the manual's caution and can damage the joint." ]},
    {heading:"Bolt identification and reuse control",paragraphs:["The covered manual uses 12-point-drive head bolts for rocker-cover clearance. It instructs the technician to paint-mark each bolt after final verification and to replace bolts that already show an earlier service paint mark. That is a service-history control, not decoration.","Keep bolt 11 visibly identified throughout cleaning and installation. Earlier Jeep service information also calls out thread sealant at this special location; confirm the complete 2001 installation section and the selected gasket instructions before applying any chemical." ]},
    {heading:"Checks that torque cannot replace",paragraphs:["Inspect the long iron head and block deck to the factory flatness limits, clean the bolt holes, and verify dowels and gasket orientation. If a bolt produces an abnormal feel or reaches its setting before the head is seated, stop and find the cause.","After the final values, check every position in sequence without loosening it. Finish the valve train, manifolds, fluids and initial start according to the full Cherokee procedure; this chart covers the head-bolt stages, not the entire repair." ]},
  ],faqs:[{q:"What are the 2001 Jeep 4.0 head-bolt stages?",a:"All 14 bolts receive 22 and 45 lb-ft passes. Bolts 1–10 and 12–14 finish at 110 lb-ft; bolt 11 finishes at 100 lb-ft."},{q:"Why is Jeep 4.0 head bolt 11 different?",a:"The factory procedure deliberately assigns bolt 11 a lower 100-lb-ft final value and warns not to overtighten it."},{q:"Can previously marked Jeep 4.0 head bolts be reused?",a:"Not under the covered procedure. It directs replacement when bolts already carry paint from an earlier service operation."},{q:"Do aftermarket Jeep 4.0 studs use these stages?",a:"No assumption is safe. Follow the stud manufacturer's procedure and specified lubricant."}]},
  "ford/300-inline-6/head-bolt-torque":{sections:[
    {heading:"The 1993 Ford three-pass chart",paragraphs:["Ford's covered 4.9L procedure uses three complete passes: 50–55 lb-ft, 60–65 lb-ft and 70–85 lb-ft. The final figure is a range tied to the application, not permission to choose 85 lb-ft for an unidentified older 300.","Follow the illustrated Ford order through every stage. Progressive tightening distributes clamp load along the unusually long inline-six head and reduces local distortion compared with finishing one bolt before its neighbors." ]},
    {heading:"Preparing a long iron head correctly",paragraphs:["Measure head and deck flatness against Ford limits and inspect for cracks, erosion and damaged bolt seats. Clean the holes and confirm bolt length and location before lowering the head over its dowels.","Use only the thread condition or sealant specified by the exact procedure. Oil, sealer and dry threads create different friction; a wrench can display the same number while the bolt produces a different clamp load." ]},
    {heading:"When the factory chart no longer applies",paragraphs:["A replacement aluminum head, performance gasket or stud kit changes the governing instructions. Use the component or fastener manufacturer's stages and lubricant rather than blending those directions with the factory-bolt ranges.","Earlier 240/300 engines and later 4.9L revisions also deserve a model-year check. Casting family alone cannot prove that bolt design, gasket construction and tightening instructions are identical." ]},
  ],faqs:[{q:"What are the 1993 Ford 300 head-bolt torque stages?",a:"For the covered F-150 4.9L, use 50–55 lb-ft, then 60–65 lb-ft, and finally 70–85 lb-ft in the factory sequence."},{q:"Should every Ford 300 head bolt be tightened directly to 85 lb-ft?",a:"No. Complete all three progressive passes in sequence; do not jump to the top of the final range."},{q:"Does this chart apply to an aluminum replacement head?",a:"Not automatically. Follow the head, gasket and fastener makers' matched procedure."},{q:"Why does thread lubricant matter?",a:"It changes friction and therefore clamp load at a given wrench reading. Use only the condition specified for the exact hardware."}]},
};

function torquePage(j: TorqueJob): SpecRecord {
  const diagramType = j.diagram ?? "head";
  const record:SpecRecord={slug:j.slug,keyword:j.keyword,make:j.make,model:j.model,category:"Torque Specs",title:j.title,
    metaDescription:`${j.title} with application boundaries, staged installation guidance, fastener cautions and official service-information source.`,
    answer:j.answer,scope:j.scope,detail:j.detail,values:j.values,sources:[j.source],reviewed,featureImage:engineImage,featureOverlay:true,
    diagram:{type:diagramType,title:`Interactive ${j.model} ${diagramType} service map`,caption:"Use the numbered map as an orientation aid only. The application-specific service diagram controls the actual bolt positions and stages.",points:j.diagram==="intake"?["1","5","3","7","9","10","8","4","6","2"]:["1","5","9","7","3","4","8","10","6","2"]},
    intro:[j.answer,j.scope],
    steps:["Identify the engine code, model year, casting, gasket and exact fastener kit before disassembly.","Clean and inspect threads, bolt holes and mating faces using the component manufacturer's limits.","Follow the exact staged pattern with the specified lubricant or sealant; record torque and angle completion."],
    sections:[{heading:`Why ${j.model} identification changes the specification`,paragraphs:[j.scope,j.detail]},{heading:"Assembly controls that prevent false torque",bullets:["Use the specified thread condition and lubricant.","Separate main bolts from small or special-position fasteners.","Use an angle gauge where torque-to-yield stages are specified.","Stop if a fastener reaches the setting before the joint seats normally."]}],
    faqs:[{q:`What is the ${j.keyword}?`,a:j.answer},{q:"Can the bolts or studs be reused?",a:"Only when the exact service procedure and fastener manufacturer allow reuse. Torque-to-yield bolts are commonly replaced."},{q:"Does an aftermarket fastener use the factory torque?",a:"Not automatically. Use the fastener maker's value, lubricant and tightening sequence for that exact kit."}]};
  const editorial=researchedTorqueEditorial[j.slug];
  if(editorial){record.sections.unshift(...editorial.sections);record.faqs=editorial.faqs;record.intro=[record.answer,j.scope,j.detail];}
  return record;
}

type FiringJob={slug:string;keyword:string;make:string;model:string;title:string;order:string;numbering:string;scope:string;detail:string;source:Source};
